       OR (SELECT count(*) FROM plt01.led_wallet_entries) <> 0
       OR (SELECT count(*) FROM plt01.led_reconciliation_cases) <> 0 THEN
        RAISE EXCEPTION 'CHECK 80 FAILED: the app role read MOD-018 rows with no context';
