             release_correlation_id, release_reason, released_at, released_by,
             session_id, source_kind, source_ref, status, taken_by, tenant_id)
        VALUES ('33333333-3333-4333-8333-333333333333',
                E'\t',
                'bbbbbbbb-1000-4000-8000-000000000002',
                1,
