                'Another policy',
                true,
                10,
                60,
                'lower case',
                'first_come',
                NULL,
                'rolling_7_days',
                NULL,
                NULL,
                NULL,
                NULL,
                'active',
                3,
                '11111111-1111-4111-8111-111111111111',
                1,
                2);
        RAISE EXCEPTION 'CHECK 97 FAILED: a policy key that is not a key';
    EXCEPTION
        WHEN check_violation THEN NULL;
    END;

