        ARRAY['acc_decision_is_coherent#12', 'INSERT INTO plt01.acc_decisions (tenant_id, decision_id, point_id, zone_id, credential_id, person_id, granted, code, public_reason, private_reason, masked, policy_id, policy_version, snapshot_id, reported_direction, device_mode, passback_scope, decided_by, correlation_id, idempotency_key) VALUES (''11111111-1111-4111-8111-111111111111'', ''88888888-5000-4000-8000-0000000000fc'', ''88888888-2000-4000-8000-000000000001'', ''88888888-1000-4000-8000-000000000001'', NULL, ''bbbbbbbb-1000-4000-8000-000000000001'', true, ''granted'', ''welcome'', ''every check passed'', false, NULL, NULL, NULL, ''entry'', ''online'', ''global'', ''33333333-3333-4333-8333-333333333333'', ''33333333-3333-4333-8333-333333333333'', ''probe-d12'')', 'a granted decision cites the policy version it satisfied'],
        ARRAY['acc_event_is_coherent#1', 'INSERT INTO plt01.acc_events (tenant_id, event_id, point_id, zone_id, direction, credential_id, person_id, decision_id, occurred_at, recorded_by, correlation_id, source, idempotency_key) VALUES (''11111111-1111-4111-8111-111111111111'', ''88888888-6000-4000-8000-0000000000f1'', ''00000000-0000-4000-8000-0000000000ff'', ''88888888-1000-4000-8000-000000000001'', ''entry'', NULL, NULL, NULL, now(), ''33333333-3333-4333-8333-333333333333'', ''33333333-3333-4333-8333-333333333333'', ''online'', ''probe-e1'')', 'this access event cites an access point that does not exist'],
        ARRAY['acc_event_is_coherent#2', 'INSERT INTO plt01.acc_events (tenant_id, event_id, point_id, zone_id, direction, credential_id, person_id, decision_id, occurred_at, recorded_by, correlation_id, source, idempotency_key) VALUES (''11111111-1111-4111-8111-111111111111'', ''88888888-6000-4000-8000-0000000000f2'', ''88888888-2000-4000-8000-000000000001'', ''88888888-1000-4000-8000-000000000002'', ''entry'', NULL, NULL, NULL, now(), ''33333333-3333-4333-8333-333333333333'', ''33333333-3333-4333-8333-333333333333'', ''online'', ''probe-e2'')', 'this access event names a zone that is not the one its point stands at'],
        ARRAY['acc_event_is_coherent#3', 'INSERT INTO plt01.acc_events (tenant_id, event_id, point_id, zone_id, direction, credential_id, person_id, decision_id, occurred_at, recorded_by, correlation_id, source, idempotency_key) VALUES (''11111111-1111-4111-8111-111111111111'', ''88888888-6000-4000-8000-0000000000f3'', ''88888888-2000-4000-8000-000000000001'', ''88888888-1000-4000-8000-000000000001'', ''exit'', NULL, NULL, NULL, now(), ''33333333-3333-4333-8333-333333333333'', ''33333333-3333-4333-8333-333333333333'', ''online'', ''probe-e3'')', 'this access point faces entry, so it did not see an exit'],
        ARRAY['acc_event_is_coherent#4', 'INSERT INTO plt01.acc_events (tenant_id, event_id, point_id, zone_id, direction, credential_id, person_id, decision_id, occurred_at, recorded_by, correlation_id, source, idempotency_key) VALUES (''11111111-1111-4111-8111-111111111111'', ''88888888-6000-4000-8000-0000000000f4'', ''88888888-2000-4000-8000-000000000001'', ''88888888-1000-4000-8000-000000000001'', ''entry'', ''00000000-0000-4000-8000-0000000000ff'', NULL, NULL, now(), ''33333333-3333-4333-8333-333333333333'', ''33333333-3333-4333-8333-333333333333'', ''online'', ''probe-e4'')', 'this access event cites a credential that does not exist'],
        ARRAY['acc_event_is_coherent#5', 'INSERT INTO plt01.acc_events (tenant_id, event_id, point_id, zone_id, direction, credential_id, person_id, decision_id, occurred_at, recorded_by, correlation_id, source, idempotency_key) VALUES (''11111111-1111-4111-8111-111111111111'', ''88888888-6000-4000-8000-0000000000f5'', ''88888888-2000-4000-8000-000000000001'', ''88888888-1000-4000-8000-000000000001'', ''entry'', ''88888888-4000-4000-8000-000000000001'', ''bbbbbbbb-1000-4000-8000-000000000002'', NULL, now(), ''33333333-3333-4333-8333-333333333333'', ''33333333-3333-4333-8333-333333333333'', ''online'', ''probe-e5'')', 'this access event names a person who does not hold the credential it cites'],
        ARRAY['acc_event_is_coherent#6', 'INSERT INTO plt01.acc_events (tenant_id, event_id, point_id, zone_id, direction, credential_id, person_id, decision_id, occurred_at, recorded_by, correlation_id, source, idempotency_key) VALUES (''11111111-1111-4111-8111-111111111111'', ''88888888-6000-4000-8000-0000000000f6'', ''88888888-2000-4000-8000-000000000001'', ''88888888-1000-4000-8000-000000000001'', ''entry'', NULL, NULL, ''00000000-0000-4000-8000-0000000000ff'', now(), ''33333333-3333-4333-8333-333333333333'', ''33333333-3333-4333-8333-333333333333'', ''online'', ''probe-e6'')', 'this access event cites a decision that does not exist'],
        ARRAY['acc_event_is_coherent#7', 'INSERT INTO plt01.acc_events (tenant_id, event_id, point_id, zone_id, direction, credential_id, person_id, decision_id, occurred_at, recorded_by, correlation_id, source, idempotency_key) VALUES (''11111111-1111-4111-8111-111111111111'', ''88888888-6000-4000-8000-0000000000f7'', ''88888888-2000-4000-8000-00000000000b'', ''88888888-1000-4000-8000-000000000001'', ''entry'', NULL, NULL, ''88888888-5000-4000-8000-000000000001'', now(), ''33333333-3333-4333-8333-333333333333'', ''33333333-3333-4333-8333-333333333333'', ''online'', ''probe-e7'')', 'this access event cites a decision made at another access point'],
        ARRAY['acc_event_is_coherent#8', 'INSERT INTO plt01.acc_events (tenant_id, event_id, point_id, zone_id, direction, credential_id, person_id, decision_id, occurred_at, recorded_by, correlation_id, source, idempotency_key) VALUES (''11111111-1111-4111-8111-111111111111'', ''88888888-6000-4000-8000-0000000000f8'', ''88888888-2000-4000-8000-000000000001'', ''88888888-1000-4000-8000-000000000001'', ''entry'', NULL, ''bbbbbbbb-1000-4000-8000-000000000002'', ''88888888-5000-4000-8000-000000000001'', now(), ''33333333-3333-4333-8333-333333333333'', ''33333333-3333-4333-8333-333333333333'', ''online'', ''probe-e8'')', 'this access event cites a decision about somebody else'],
        ARRAY['acc_event_is_coherent#9', 'INSERT INTO plt01.acc_events (tenant_id, event_id, point_id, zone_id, direction, credential_id, person_id, decision_id, occurred_at, recorded_by, correlation_id, source, idempotency_key) VALUES (''11111111-1111-4111-8111-111111111111'', ''88888888-6000-4000-8000-0000000000f9'', ''88888888-2000-4000-8000-000000000001'', ''88888888-1000-4000-8000-000000000001'', ''entry'', NULL, ''bbbbbbbb-1000-4000-8000-000000000001'', ''88888888-5000-4000-8000-000000000002'', now(), ''33333333-3333-4333-8333-333333333333'', ''33333333-3333-4333-8333-333333333333'', ''online'', ''probe-e9'')', 'this entry cites a decision that refused it'],
        ARRAY['setup', 'UPDATE plt01.acc_points SET status = ''retired'', retired_at = now(), retired_by = ''33333333-3333-4333-8333-333333333333'', retire_reason = ''the west turnstile was removed'', retire_correlation_id = ''33333333-3333-4333-8333-333333333333'' WHERE point_id = ''88888888-2000-4000-8000-00000000000b''', ''],
        ARRAY['acc_decision_is_coherent#4', 'INSERT INTO plt01.acc_decisions (tenant_id, decision_id, point_id, zone_id, credential_id, person_id, granted, code, public_reason, private_reason, masked, policy_id, policy_version, snapshot_id, reported_direction, device_mode, passback_scope, decided_by, correlation_id, idempotency_key) VALUES (''11111111-1111-4111-8111-111111111111'', ''88888888-5000-4000-8000-0000000000f4'', ''88888888-2000-4000-8000-00000000000b'', ''88888888-1000-4000-8000-000000000001'', NULL, NULL, false, ''outstanding_balance'', ''please see the front desk'', ''this member owes 4500 in minor units'', true, NULL, NULL, NULL, ''entry'', ''online'', ''global'', ''33333333-3333-4333-8333-333333333333'', ''33333333-3333-4333-8333-333333333333'', ''probe-d4'')', 'this access point is retired; it decides nothing'],
        ARRAY['acc_decision_is_final#1', 'UPDATE plt01.acc_decisions SET private_reason = ''on reflection, fine'' WHERE decision_id = ''88888888-5000-4000-8000-000000000002''', 'an access decision is what was decided at the door'],
        ARRAY['setup', 'UPDATE plt01.acc_events SET reconciled_outcome = ''accepted'', reconciled_at = now(), reconciled_by = ''33333333-3333-4333-8333-333333333333'', reconcile_correlation_id = ''33333333-3333-4333-8333-333333333333'' WHERE event_id = ''88888888-6000-4000-8000-000000000001''', ''],
        ARRAY['acc_event_is_one_way#1', 'UPDATE plt01.acc_events SET direction = ''exit'' WHERE event_id = ''88888888-6000-4000-8000-000000000001''', 'an access event is what a reader saw'],
        ARRAY['acc_event_is_one_way#2', 'UPDATE plt01.acc_events SET reconciled_outcome = ''duplicate'' WHERE event_id = ''88888888-6000-4000-8000-000000000001''', 'this event was reconciled on'],
        ARRAY['setup', 'UPDATE plt01.acc_emergency_unlocks SET reviewed_at = now(), reviewed_by = ''44444444-4444-4444-8444-444444444444'', review_note = ''the alarm was genuine'', review_correlation_id = ''33333333-3333-4333-8333-333333333333'' WHERE unlock_id = ''88888888-7000-4000-8000-000000000001''', ''],
        ARRAY['acc_emergency_is_one_way#1', 'UPDATE plt01.acc_emergency_unlocks SET reason = ''a drill, not a fire'' WHERE unlock_id = ''88888888-7000-4000-8000-000000000001''', 'what was released, where, why and by whom is what an emergency unlock is'],
        ARRAY['acc_emergency_is_one_way#2', 'UPDATE plt01.acc_emergency_unlocks SET review_note = ''on reflection, a drill'' WHERE unlock_id = ''88888888-7000-4000-8000-000000000001''', 'this emergency unlock was reviewed on']
    ];
BEGIN
    PERFORM set_config('app.tenant_id', '11111111-1111-4111-8111-111111111111', true);
    FOREACH one SLICE 1 IN ARRAY cases LOOP
        IF one[3] = '' THEN
            -- A fixture statement. It must work, or every probe after it proves nothing.
            BEGIN
                EXECUTE one[2];
            EXCEPTION WHEN others THEN
                RAISE EXCEPTION
                    'CHECK 111 FAILED: the fixture for % was refused (%): %',
                    one[1], sqlstate, sqlerrm;
            END;
        ELSE
            BEGIN
                EXECUTE one[2];
                RAISE EXCEPTION
                    'CHECK 111 FAILED: % admitted the row it exists to refuse', one[1];
            EXCEPTION
                WHEN raise_exception THEN
                    IF sqlerrm LIKE 'CHECK 111 FAILED%' THEN RAISE; END IF;
                    IF position(one[3] in sqlerrm) = 0 THEN
                        -- Another branch of the same function answered, which is the trap
                        -- this block is written against: the probe proves whichever
                        -- control replies, so it has to say which.
                        confused := array_append(
                            confused, one[1] || ' (answered: ' || sqlerrm || ')');
                    ELSE
                        probe := probe + 1;
                    END IF;
                WHEN others THEN
                    -- A key or a CHECK refused it instead. Recorded, never counted: that
                    -- is the false green the whole discipline exists to prevent.
                    confused := array_append(
                        confused, one[1] || ' (answered by ' || sqlstate || ': '
                                  || sqlerrm || ')');
            END;
        END IF;
    END LOOP;

    IF array_length(confused, 1) IS NOT NULL THEN
        RAISE EXCEPTION
            'CHECK 111 FAILED: these branch probes were answered by something other than '
            'the branch they name, so they prove the wrong control: %',
            array_to_string(confused, ' | ');
    END IF;
    IF probe <> 44 THEN
        RAISE EXCEPTION 'CHECK 111 FAILED: ran % of 44 MOD-022 trigger-branch probes',
            probe;
    END IF;
    -- **And the count is compared against the catalogue, not just against itself.** A probe
    -- count asserted as a literal notices a probe that stops firing and says nothing about a
    -- branch somebody adds later -- which is the per-table-list failure this file records for
    -- grants, policies and constraints, one level in. Counting the `RAISE` statements in the
    -- module's own trigger functions means a new refusal with no probe fails here.
    SELECT sum((length(prosrc) - length(replace(prosrc, 'RAISE EXCEPTION', '')))
               / length('RAISE EXCEPTION'))
      INTO declared
      FROM pg_proc
     WHERE pronamespace = 'plt01'::regnamespace AND proname LIKE 'acc\_%';
    IF declared <> probe THEN
        RAISE EXCEPTION
            'CHECK 111 FAILED: MOD-022 trigger functions raise % refusals and this block '
            'probes %: a branch was added or removed without its probe', declared, probe;
    END IF;
END $$;
ROLLBACK;

-- ========================================================= CHECK 112 (MOD-026)
--
-- The module's own structure, because the prefix-free sweeps prove the schema-wide rules --
-- RLS, the policy predicate, the tenant foreign key, the tenant-leading key, the privilege
-- bans and the forbidden names -- and nothing about *this* module. What is here is the three
-- pins this file has learned to require per module, each compared as a set in both
-- directions: the column-level UPDATE grants per role, every NOT NULL, and every foreign key.
--
-- A per-table list is the thing that goes stale when a module adds a table, and that edit is
-- the moment an unprotected one slips through -- so each comparison is against the catalogue.
BEGIN;
DO $$
DECLARE
    wrong text;
BEGIN
    -- ---- the UPDATE grants, per role and per column, both directions.
    --
    -- MOD-016 claimed in three places that a table carried no UPDATE grant while
    -- `effective_to` was in it, and MOD-019 granted three rota columns no service ever wrote.
    -- A granted column nothing writes is an unattributed edit path, so the list is pinned.
    FOR wrong IN
        WITH expected(t, c) AS (VALUES
            ('tsk_queues', 'display_name'), ('tsk_queues', 'status'),
            ('tsk_queues', 'retired_at'), ('tsk_queues', 'retired_by'),
            ('tsk_queues', 'retire_reason'), ('tsk_queues', 'retire_correlation_id'),
            ('tsk_business_hours', 'withdrawn_at'), ('tsk_business_hours', 'withdrawn_by'),
            ('tsk_business_hours', 'withdraw_reason'),
            ('tsk_business_hours', 'withdraw_correlation_id'),
            ('tsk_cases', 'title'), ('tsk_cases', 'queue_id'), ('tsk_cases', 'priority'),
            ('tsk_cases', 'status'), ('tsk_cases', 'resolved_at'),
            ('tsk_cases', 'resolved_by'), ('tsk_cases', 'resolution_reason'),
            ('tsk_cases', 'resolve_correlation_id'),
            -- `0024`: the owner ADM-CC-06's four assignment states need, and the snooze
            -- five. **Not `source`** -- where work came from does not change.
            ('tsk_cases', 'assignee_person_id'), ('tsk_cases', 'snoozed_at'),
            ('tsk_cases', 'snoozed_until'), ('tsk_cases', 'snooze_reason'),
            ('tsk_cases', 'snoozed_by'), ('tsk_cases', 'snooze_correlation_id'),
            ('tsk_case_affected', 'withdrawn_at'),
            ('tsk_case_affected', 'withdrawn_by'),
            ('tsk_case_affected', 'withdraw_reason'),
            ('tsk_case_affected', 'withdraw_correlation_id'),
            ('tsk_tasks', 'queue_id'), ('tsk_tasks', 'case_id'), ('tsk_tasks', 'title'),
            ('tsk_tasks', 'assignee_person_id'), ('tsk_tasks', 'priority'),
            ('tsk_tasks', 'status'), ('tsk_tasks', 'due_at'),
            ('tsk_tasks', 'evidence_ref'), ('tsk_tasks', 'settled_at'),
            ('tsk_tasks', 'settled_by'), ('tsk_tasks', 'settle_reason'),
            ('tsk_tasks', 'settle_correlation_id'),
            ('tsk_checklist_items', 'label'), ('tsk_checklist_items', 'completed_at'),
            ('tsk_checklist_items', 'completed_by'),
            ('tsk_checklist_items', 'complete_correlation_id'),
            ('tsk_sla_clocks', 'status'), ('tsk_sla_clocks', 'settled_at'),
            ('tsk_sla_clocks', 'settled_by'), ('tsk_sla_clocks', 'settle_reason'),
            ('tsk_sla_clocks', 'settle_correlation_id'),
            ('tsk_sla_clocks', 'escalate_to_queue_id'),
            ('tsk_sla_clocks', 'warn_at_basis_points'),
            ('tsk_sla_pauses', 'resumed_at'), ('tsk_sla_pauses', 'resumed_by'),
            ('tsk_sla_pauses', 'resume_correlation_id')),
        actual(role, t, c) AS (
            SELECT r.rolname, cl.relname::text, a.attname::text
              FROM pg_class cl
              JOIN pg_attribute a ON a.attrelid = cl.oid AND a.attnum > 0 AND NOT a.attisdropped
              CROSS JOIN (VALUES ('veyro_cp_app'), ('veyro_cp_worker')) AS rr(rolname)
              JOIN pg_roles r ON r.rolname = rr.rolname
             WHERE cl.relnamespace = 'plt01'::regnamespace
               AND cl.relkind IN ('r', 'p')
               AND cl.relname LIKE 'tsk\_%'
               AND has_column_privilege(r.rolname, cl.oid, a.attname, 'UPDATE'))
        SELECT format('%s has UPDATE on %s.%s which is not in the pin', role, t, c)
          FROM actual WHERE (t, c) NOT IN (SELECT t, c FROM expected)
        UNION ALL
        SELECT format('%s.%s is pinned as updatable and no role holds it', t, c)
          FROM expected e
         WHERE NOT EXISTS (SELECT 1 FROM actual a WHERE a.t = e.t AND a.c = e.c)
    LOOP
        RAISE EXCEPTION 'CHECK 112 FAILED: %', wrong;
    END LOOP;

    -- ---- every NOT NULL, as a set.
    --
    -- Nothing in this file had read `attnotnull` until MOD-016, where 80 of 84 missed
    -- mutations were `DROP NOT NULL`. It matters twice over: a NOT NULL is what makes a
    -- sibling CHECK bite (a NULL operand makes the whole predicate NULL and a CHECK passes on
    -- NULL), and under MATCH SIMPLE a NULL in any column of a composite foreign key skips the
    -- whole check -- so dropping it from `tsk_tasks.queue_id` silently switches off a
    -- tenant-carrying parent reference the foreign-key set comparison cannot see.
    FOR wrong IN
        WITH expected(t, c) AS (VALUES
            ('tsk_queues', 'tenant_id'), ('tsk_queues', 'queue_id'),
            ('tsk_queues', 'queue_key'), ('tsk_queues', 'display_name'),
            ('tsk_queues', 'status'), ('tsk_queues', 'created_at'),
            ('tsk_queues', 'created_by'), ('tsk_queues', 'create_correlation_id'),
            ('tsk_business_hours', 'tenant_id'), ('tsk_business_hours', 'window_id'),
            ('tsk_business_hours', 'location_id'), ('tsk_business_hours', 'kind'),
            ('tsk_business_hours', 'created_at'), ('tsk_business_hours', 'created_by'),
            ('tsk_business_hours', 'create_correlation_id'),
            ('tsk_cases', 'tenant_id'), ('tsk_cases', 'case_id'),
            ('tsk_cases', 'case_number'), ('tsk_cases', 'title'),
            ('tsk_cases', 'queue_id'), ('tsk_cases', 'subject_kind'),
            ('tsk_cases', 'priority'), ('tsk_cases', 'status'),
            ('tsk_cases', 'opened_at'), ('tsk_cases', 'opened_by'),
            ('tsk_cases', 'open_correlation_id'),
            ('tsk_cases', 'idempotency_key'), ('tsk_cases', 'source'),
            ('tsk_case_affected', 'tenant_id'), ('tsk_case_affected', 'case_id'),
            ('tsk_case_affected', 'affected_kind'), ('tsk_case_affected', 'affected_id'),
            ('tsk_case_affected', 'added_at'), ('tsk_case_affected', 'added_by'),
            ('tsk_case_affected', 'correlation_id'),
            ('tsk_case_entries', 'tenant_id'), ('tsk_case_entries', 'entry_id'),
            ('tsk_case_entries', 'case_id'), ('tsk_case_entries', 'entry_kind'),
            ('tsk_case_entries', 'summary'), ('tsk_case_entries', 'occurred_at'),
            ('tsk_case_entries', 'recorded_at'), ('tsk_case_entries', 'recorded_by'),
            ('tsk_case_entries', 'correlation_id'),
            ('tsk_tasks', 'tenant_id'), ('tsk_tasks', 'task_id'),
            ('tsk_tasks', 'queue_id'), ('tsk_tasks', 'title'),
            ('tsk_tasks', 'subject_kind'), ('tsk_tasks', 'priority'),
            ('tsk_tasks', 'status'), ('tsk_tasks', 'created_at'),
            ('tsk_tasks', 'created_by'), ('tsk_tasks', 'create_correlation_id'),
            ('tsk_tasks', 'idempotency_key'), ('tsk_tasks', 'source'),
            ('tsk_checklist_items', 'tenant_id'), ('tsk_checklist_items', 'item_id'),
            ('tsk_checklist_items', 'task_id'), ('tsk_checklist_items', 'ordinal'),
            ('tsk_checklist_items', 'label'), ('tsk_checklist_items', 'created_at'),
            ('tsk_checklist_items', 'created_by'),
            ('tsk_checklist_items', 'create_correlation_id'),
            ('tsk_dependencies', 'tenant_id'), ('tsk_dependencies', 'dependency_id'),
            ('tsk_dependencies', 'task_id'), ('tsk_dependencies', 'depends_on_task_id'),
            ('tsk_dependencies', 'created_at'), ('tsk_dependencies', 'created_by'),
            ('tsk_dependencies', 'create_correlation_id'),
            ('tsk_sla_clocks', 'tenant_id'), ('tsk_sla_clocks', 'clock_id'),
            ('tsk_sla_clocks', 'location_id'), ('tsk_sla_clocks', 'target_seconds'),
            ('tsk_sla_clocks', 'warn_at_basis_points'), ('tsk_sla_clocks', 'started_at'),
            ('tsk_sla_clocks', 'status'), ('tsk_sla_clocks', 'created_at'),
            ('tsk_sla_clocks', 'created_by'), ('tsk_sla_clocks', 'create_correlation_id'),
            ('tsk_sla_pauses', 'tenant_id'), ('tsk_sla_pauses', 'pause_id'),
            ('tsk_sla_pauses', 'clock_id'), ('tsk_sla_pauses', 'paused_at'),
            ('tsk_sla_pauses', 'reason'), ('tsk_sla_pauses', 'paused_by'),
            ('tsk_sla_pauses', 'pause_correlation_id')),
        actual(t, c) AS (
            SELECT cl.relname::text, a.attname::text
              FROM pg_class cl
              JOIN pg_attribute a ON a.attrelid = cl.oid AND a.attnum > 0
                                 AND NOT a.attisdropped AND a.attnotnull
             WHERE cl.relnamespace = 'plt01'::regnamespace
               AND cl.relkind IN ('r', 'p') AND cl.relname LIKE 'tsk\_%')
        SELECT format('%s.%s is NOT NULL and the pin does not say so', t, c)
          FROM actual WHERE (t, c) NOT IN (SELECT t, c FROM expected)
        UNION ALL
        SELECT format('%s.%s is pinned NOT NULL and is nullable', t, c)
          FROM expected WHERE (t, c) NOT IN (SELECT t, c FROM actual)
    LOOP
        RAISE EXCEPTION 'CHECK 112 FAILED: %', wrong;
    END LOOP;

    -- ---- no stored countdown, anywhere under this prefix.
    --
    -- **The absence is the control, and an absence is what a later migration restores.** An
    -- SLA clock is its target, its calendar and its pauses, and the remaining time is a
    -- function of those and `now()`; a column holding the answer is a second copy of the
    -- truth that goes stale between writes, and a `breached` flag is the same thing with
    -- fewer values. MOD-018 sweeps for a cached balance and MOD-019 for a `held_count` for
    -- exactly this reason -- and `0021`'s own header claimed this sweep existed before it
    -- did, which is the "a doc claiming a control it does not have" shape caught by writing
    -- the control.
    --
    -- `due_at` is banned on the clock tables only: it is a derivation there and a perfectly
    -- ordinary caller-stated field on a task.
    FOR wrong IN
        SELECT format('%s.%s', cl.relname, a.attname)
          FROM pg_class cl
          JOIN pg_attribute a ON a.attrelid = cl.oid AND a.attnum > 0 AND NOT a.attisdropped
         WHERE cl.relnamespace = 'plt01'::regnamespace
           AND cl.relkind IN ('r', 'p')
           AND cl.relname LIKE 'tsk\_%'
           AND (a.attname IN ('seconds_remaining', 'minutes_remaining', 'time_remaining',
                              'remaining_seconds', 'remaining_minutes', 'elapsed_seconds',
                              'breached', 'is_breached', 'sla_state', 'breach_at',
                              'open_seconds', 'business_seconds')
                OR (cl.relname LIKE 'tsk\_sla\_%' AND a.attname = 'due_at'))
    LOOP
        RAISE EXCEPTION
            'CHECK 112 FAILED: % is a stored countdown, and an SLA clock derives its '
            'remaining time from its target, its calendar and its pauses -- a column '
            'holding the answer is a second copy of the truth that goes stale', wrong;
    END LOOP;

    -- ---- every foreign key, as a set.
    --
    -- MOD-012's lesson: a sweep of one *kind* of reference is not a sweep. Its check swept the
    -- tenant-registry key across every table and sampled the intra-module parents, which left
    -- two droppable in silence -- including the self-reference that was the only thing keeping
    -- a credential's predecessor inside its own tenant. `tsk_cases.recurs_from_case_id` is
    -- exactly that shape here.
    -- **No separate count, because the set comparison below is strictly stronger and a
    -- literal beside it is a second statement that can disagree.** The first version of this
    -- check carried `IF n <> 13`, which was simply a miscount -- the pinned list has 18
    -- entries -- and the suite failed on the literal rather than on anything about the
    -- schema. A subsumed check is deleted rather than tested harder, which is the judgement
    -- this file records for MOD-016's redundant kind domain and MOD-020's three siblings.
    FOR wrong IN
        WITH expected(t, def) AS (VALUES
            ('tsk_queues', 'FOREIGN KEY (tenant_id) REFERENCES plt01_platform.tenants(tenant_id)'),
            ('tsk_queues', 'FOREIGN KEY (tenant_id, location_id) REFERENCES plt01.locations(tenant_id, location_id)'),
            ('tsk_business_hours', 'FOREIGN KEY (tenant_id) REFERENCES plt01_platform.tenants(tenant_id)'),
            ('tsk_business_hours', 'FOREIGN KEY (tenant_id, location_id) REFERENCES plt01.locations(tenant_id, location_id)'),
            ('tsk_cases', 'FOREIGN KEY (tenant_id) REFERENCES plt01_platform.tenants(tenant_id)'),
            ('tsk_cases', 'FOREIGN KEY (tenant_id, queue_id) REFERENCES plt01.tsk_queues(tenant_id, queue_id)'),
            ('tsk_cases', 'FOREIGN KEY (tenant_id, recurs_from_case_id) REFERENCES plt01.tsk_cases(tenant_id, case_id)'),
            ('tsk_cases', 'FOREIGN KEY (tenant_id, assignee_person_id) REFERENCES plt01.ppl_persons(tenant_id, person_id)'),
            ('tsk_case_affected', 'FOREIGN KEY (tenant_id) REFERENCES plt01_platform.tenants(tenant_id)'),
            ('tsk_case_affected', 'FOREIGN KEY (tenant_id, case_id) REFERENCES plt01.tsk_cases(tenant_id, case_id)'),
            ('tsk_case_entries', 'FOREIGN KEY (tenant_id) REFERENCES plt01_platform.tenants(tenant_id)'),
            ('tsk_case_entries', 'FOREIGN KEY (tenant_id, case_id) REFERENCES plt01.tsk_cases(tenant_id, case_id)'),
            ('tsk_tasks', 'FOREIGN KEY (tenant_id) REFERENCES plt01_platform.tenants(tenant_id)'),
            ('tsk_tasks', 'FOREIGN KEY (tenant_id, queue_id) REFERENCES plt01.tsk_queues(tenant_id, queue_id)'),
            ('tsk_tasks', 'FOREIGN KEY (tenant_id, case_id) REFERENCES plt01.tsk_cases(tenant_id, case_id)'),
            ('tsk_tasks', 'FOREIGN KEY (tenant_id, assignee_person_id) REFERENCES plt01.ppl_persons(tenant_id, person_id)'),
            ('tsk_checklist_items', 'FOREIGN KEY (tenant_id) REFERENCES plt01_platform.tenants(tenant_id)'),
            ('tsk_checklist_items', 'FOREIGN KEY (tenant_id, task_id) REFERENCES plt01.tsk_tasks(tenant_id, task_id)'),
            ('tsk_dependencies', 'FOREIGN KEY (tenant_id) REFERENCES plt01_platform.tenants(tenant_id)'),
            ('tsk_dependencies', 'FOREIGN KEY (tenant_id, task_id) REFERENCES plt01.tsk_tasks(tenant_id, task_id)'),
            ('tsk_dependencies', 'FOREIGN KEY (tenant_id, depends_on_task_id) REFERENCES plt01.tsk_tasks(tenant_id, task_id)'),
            ('tsk_sla_clocks', 'FOREIGN KEY (tenant_id) REFERENCES plt01_platform.tenants(tenant_id)'),
            ('tsk_sla_clocks', 'FOREIGN KEY (tenant_id, task_id) REFERENCES plt01.tsk_tasks(tenant_id, task_id)'),
            ('tsk_sla_clocks', 'FOREIGN KEY (tenant_id, case_id) REFERENCES plt01.tsk_cases(tenant_id, case_id)'),
            ('tsk_sla_clocks', 'FOREIGN KEY (tenant_id, location_id) REFERENCES plt01.locations(tenant_id, location_id)'),
            ('tsk_sla_clocks', 'FOREIGN KEY (tenant_id, escalate_to_queue_id) REFERENCES plt01.tsk_queues(tenant_id, queue_id)'),
            ('tsk_sla_pauses', 'FOREIGN KEY (tenant_id) REFERENCES plt01_platform.tenants(tenant_id)'),
            ('tsk_sla_pauses', 'FOREIGN KEY (tenant_id, clock_id) REFERENCES plt01.tsk_sla_clocks(tenant_id, clock_id)')),
        actual(t, def) AS (
            SELECT cl.relname::text, pg_get_constraintdef(c.oid)
              FROM pg_constraint c
              JOIN pg_class cl ON cl.oid = c.conrelid
             WHERE cl.relnamespace = 'plt01'::regnamespace
               AND cl.relname LIKE 'tsk\_%' AND c.contype = 'f')
        SELECT format('%s carries %s which is not pinned', t, def)
          FROM actual WHERE (t, def) NOT IN (SELECT t, def FROM expected)
        UNION ALL
        SELECT format('%s is pinned to carry %s and does not', t, def)
          FROM expected WHERE (t, def) NOT IN (SELECT t, def FROM actual)
    LOOP
        RAISE EXCEPTION 'CHECK 112 FAILED: %', wrong;
    END LOOP;
END $$;
ROLLBACK;

-- ========================================================= CHECK 113 (MOD-026)
--
-- INV-AUT-02 in the database, and the snapshot it rests on.
--
-- Two halves, and neither is evidence without the other. The trigger refuses an approver who
-- is the requester **when the request's snapshot says separation of duties applies** -- so a
-- policy that permits self-approval still can, which is the invariant's own "unless explicit
-- emergency policy applies". And the snapshot has to be a snapshot: MOD-008's review found
-- that re-deriving the terms let somebody switch separation of duties off for a request
-- already in flight, and the fix left the snapshotted column itself writable by a table-wide
-- grant.
BEGIN;
SET LOCAL app.tenant_id = '11111111-1111-4111-8111-111111111111';
DO $$
DECLARE
    probe integer := 0;
    offender text;
BEGIN
    -- ---- the grant: two columns, and not the terms.
    IF has_table_privilege('veyro_iam_app', 'iam.approval_requests', 'UPDATE') THEN
        RAISE EXCEPTION
            'CHECK 113 FAILED: iam.approval_requests carries a table-wide UPDATE grant, so '
            'the snapshotted terms an approval rests on are rewritable';
    END IF;
    IF NOT has_column_privilege('veyro_iam_app', 'iam.approval_requests', 'state', 'UPDATE')
       OR NOT has_column_privilege('veyro_iam_app', 'iam.approval_requests', 'decided_at',
                                   'UPDATE') THEN
        RAISE EXCEPTION
            'CHECK 113 FAILED: the service settles a request by writing state and '
            'decided_at, and one of them is not granted';
    END IF;
    FOR offender IN
        SELECT a.attname::text
          FROM pg_class c
          JOIN pg_attribute a ON a.attrelid = c.oid AND a.attnum > 0 AND NOT a.attisdropped
         WHERE c.relnamespace = 'iam'::regnamespace
           AND c.relname = 'approval_requests'
           AND a.attname NOT IN ('state', 'decided_at')
           AND has_column_privilege('veyro_iam_app', c.oid, a.attname, 'UPDATE')
    LOOP
        RAISE EXCEPTION
            'CHECK 113 FAILED: veyro_iam_app can write iam.approval_requests.%, which the '
            'service never does -- a granted column no service writes is an unattributed '
            'edit path, and this one is through the terms an approval cites', offender;
    END LOOP;

    -- ---- the trigger, branch by branch.
    --
    -- Branch 1: separation of duties applies and the decider is the requester. The seeded
    -- request `...0004` is `separation_of_duties = true`, requested by `...0002`.
    BEGIN
        INSERT INTO iam.approval_decisions (tenant_id, request_id, decided_by, decision)
        VALUES ('11111111-1111-4111-8111-111111111111',
                'ffffffff-0000-4000-8000-000000000004',
                'eeeeeeee-0000-4000-8000-000000000002', 'approved');
        RAISE EXCEPTION
            'CHECK 113 FAILED: the requester decided their own request under separation of '
            'duties';
    EXCEPTION
        WHEN raise_exception THEN
            IF sqlerrm LIKE 'CHECK 113 FAILED%' THEN RAISE; END IF;
            -- **The sentence, not the exception class.** A `NOT EXISTS`-shaped branch above
            -- answers for a missing parent, and the unique index answers for a repeat; a
            -- probe counting any `raise_exception` would be satisfied by either.
            IF sqlerrm NOT LIKE '%may not decide their own request%' THEN
                RAISE EXCEPTION
                    'CHECK 113 FAILED: the self-approval was refused by something else: %',
                    sqlerrm;
            END IF;
            probe := probe + 1;
    END;

    -- Branch 2, the permission rather than the refusal: with the snapshot saying separation
    -- of duties does **not** apply, the same person may decide. Without this the trigger
    -- could refuse unconditionally and nothing would notice -- which is the version the
    -- service does not implement, and two encodings that disagree is MOD-020's waitlist edge.
    INSERT INTO iam.approval_requests
        (tenant_id, request_id, action, resource_type, requested_by, required_approvals,
         separation_of_duties, required_permissions, expires_at)
    VALUES ('11111111-1111-4111-8111-111111111111',
            'ffffffff-0000-4000-8000-00000000000e', 'billing.refund.issue', 'invoice',
            'eeeeeeee-0000-4000-8000-000000000002', 1, false,
            ARRAY['billing.refund.approve'], now() + interval '1 day');
    -- **Wrapped, because a probe has to fail under its own name.** Written as a bare INSERT
    -- this aborted the block with the *trigger's* message when the trigger was wrong, which
    -- a sweep cannot tell from an unrelated error -- it reported MUTERR for a mutation this
    -- branch had correctly caught. A probe that proves a permission needs a handler exactly
    -- as much as one that proves a refusal.
    BEGIN
        INSERT INTO iam.approval_decisions (tenant_id, request_id, decided_by, decision)
        VALUES ('11111111-1111-4111-8111-111111111111',
                'ffffffff-0000-4000-8000-00000000000e',
                'eeeeeeee-0000-4000-8000-000000000002', 'approved');
        probe := probe + 1;
    EXCEPTION
        WHEN OTHERS THEN
            RAISE EXCEPTION
                'CHECK 113 FAILED: a policy that permits self-approval was refused anyway, '
                'so the trigger and app/authorization/approval.py disagree: %', sqlerrm;
    END;

    -- Branch 3: a decision naming a request that does not exist is the **foreign key's**
    -- refusal and not the trigger's. The trigger returns rather than raising there precisely
    -- so the two stay distinguishable -- MOD-019's two session triggers and MOD-021's three
    -- `NOT EXISTS` branches are what that costs when they do not.
    BEGIN
        INSERT INTO iam.approval_decisions (tenant_id, request_id, decided_by, decision)
        VALUES ('11111111-1111-4111-8111-111111111111',
                'ffffffff-0000-4000-8000-0000000000ff',
                'eeeeeeee-0000-4000-8000-000000000002', 'approved');
        RAISE EXCEPTION
            'CHECK 113 FAILED: a decision was recorded against a request that does not exist';
    EXCEPTION
        WHEN raise_exception THEN
            IF sqlerrm LIKE 'CHECK 113 FAILED%' THEN RAISE; END IF;
            RAISE EXCEPTION
                'CHECK 113 FAILED: the missing request was refused by the trigger rather '
                'than by the foreign key, so the two cannot be told apart: %', sqlerrm;
        WHEN foreign_key_violation THEN
            probe := probe + 1;
    END;

    -- ---- delegation: four more branches, each probed by its own sentence.
    --
    -- Two extra identities, created here and rolled back with the block: the transitivity
    -- refusals need three people, and the seed has two.
    INSERT INTO iam.identities (tenant_id, identity_id, person_id, email_normalized,
                                display_name)
    VALUES ('11111111-1111-4111-8111-111111111111',
            'eeeeeeee-0000-4000-8000-00000000000c',
            'eeeeeeee-0000-4000-8000-00000000000d', 'deputy@acme.test', 'Acme Deputy'),
           ('11111111-1111-4111-8111-111111111111',
            'eeeeeeee-0000-4000-8000-00000000000e',
            'eeeeeeee-0000-4000-8000-00000000000f', 'third@acme.test', 'Acme Third');

    -- Branch 4: a decision citing an authority nobody granted. **"A cited authority is the
    -- authority, or it is decoration"** -- without this, `on_behalf_of` is a text field that
    -- says whatever the caller types.
    BEGIN
        INSERT INTO iam.approval_decisions
            (tenant_id, request_id, decided_by, decision, on_behalf_of)
        VALUES ('11111111-1111-4111-8111-111111111111',
                'ffffffff-0000-4000-8000-000000000004',
                'eeeeeeee-0000-4000-8000-00000000000c', 'approved',
                'eeeeeeee-0000-4000-8000-00000000000e');
        RAISE EXCEPTION
            'CHECK 113 FAILED: a decision claimed an authority no delegation granted';
    EXCEPTION
        WHEN raise_exception THEN
            IF sqlerrm LIKE 'CHECK 113 FAILED%' THEN RAISE; END IF;
            IF sqlerrm NOT LIKE '%no live delegation grants it%' THEN
                RAISE EXCEPTION
                    'CHECK 113 FAILED: the ungranted authority was refused by something '
                    'else: %', sqlerrm;
            END IF;
            probe := probe + 1;
    END;

    -- A live delegation, so the next two branches have one to work against: the requester
    -- (`...0002`) delegates to the deputy (`...000c`).
    INSERT INTO iam.approval_delegations
        (tenant_id, from_identity_id, to_identity_id, starts_at, ends_at, reason,
         created_by, create_correlation_id)
    VALUES ('11111111-1111-4111-8111-111111111111',
            'eeeeeeee-0000-4000-8000-000000000002',
            'eeeeeeee-0000-4000-8000-00000000000c',
            now() - interval '1 hour', now() + interval '7 days', 'away this week',
            'eeeeeeee-0000-4000-8000-000000000002',
            '33333333-3333-4333-8333-333333333333');

    -- Branch 5: **the whole reason this migration exists.** The deputy now holds the
    -- requester's authority, so deciding the requester's own request on it is the requester
    -- approving themselves through a proxy -- separation of duties intact in the column and
    -- gone in fact.
    BEGIN
        INSERT INTO iam.approval_decisions
            (tenant_id, request_id, decided_by, decision, on_behalf_of)
        VALUES ('11111111-1111-4111-8111-111111111111',
                'ffffffff-0000-4000-8000-000000000004',
                'eeeeeeee-0000-4000-8000-00000000000c', 'approved',
                'eeeeeeee-0000-4000-8000-000000000002');
        RAISE EXCEPTION
            'CHECK 113 FAILED: the requester decided their own request through a delegate';
    EXCEPTION
        WHEN raise_exception THEN
            IF sqlerrm LIKE 'CHECK 113 FAILED%' THEN RAISE; END IF;
            IF sqlerrm NOT LIKE '%through a delegate%' THEN
                RAISE EXCEPTION
                    'CHECK 113 FAILED: the proxy self-approval was refused by something '
                    'else, so the delegation clause proves nothing: %', sqlerrm;
            END IF;
            probe := probe + 1;
    END;

    -- Branch 6: the deputy holds a delegation, so they may not take another one on.
    BEGIN
        INSERT INTO iam.approval_delegations
            (tenant_id, from_identity_id, to_identity_id, starts_at, ends_at, reason,
             created_by, create_correlation_id)
        VALUES ('11111111-1111-4111-8111-111111111111',
                'eeeeeeee-0000-4000-8000-00000000000c',
                'eeeeeeee-0000-4000-8000-00000000000e',
                now(), now() + interval '1 day', 'passing it on',
                'eeeeeeee-0000-4000-8000-00000000000c',
                '33333333-3333-4333-8333-333333333333');
        RAISE EXCEPTION 'CHECK 113 FAILED: a delegation was passed on';
    EXCEPTION
        WHEN raise_exception THEN
            IF sqlerrm LIKE 'CHECK 113 FAILED%' THEN RAISE; END IF;
            IF sqlerrm NOT LIKE '%is not passed on%' THEN
                RAISE EXCEPTION
                    'CHECK 113 FAILED: the onward delegation was refused by something '
                    'else: %', sqlerrm;
            END IF;
            probe := probe + 1;
    END;

    -- Branch 7: the other direction. Somebody who has delegated their own approvals away
    -- cannot hold anybody else's, which is the same chain seen from the far end.
    BEGIN
        INSERT INTO iam.approval_delegations
            (tenant_id, from_identity_id, to_identity_id, starts_at, ends_at, reason,
             created_by, create_correlation_id)
        VALUES ('11111111-1111-4111-8111-111111111111',
                'eeeeeeee-0000-4000-8000-00000000000e',
                'eeeeeeee-0000-4000-8000-000000000002',
                now(), now() + interval '1 day', 'covering for the third',
                'eeeeeeee-0000-4000-8000-00000000000e',
                '33333333-3333-4333-8333-333333333333');
        RAISE EXCEPTION
            'CHECK 113 FAILED: somebody who delegated their approvals away took another on';
    EXCEPTION
        WHEN raise_exception THEN
            IF sqlerrm LIKE 'CHECK 113 FAILED%' THEN RAISE; END IF;
            IF sqlerrm NOT LIKE '%delegated their own approvals away%' THEN
                RAISE EXCEPTION
                    'CHECK 113 FAILED: the reverse chain was refused by something else: %',
                    sqlerrm;
            END IF;
            probe := probe + 1;
    END;

    -- Branches 4a and 4b: the **weakenings**, which the probe above cannot see. It cites a
    -- delegation that does not exist, so dropping `revoked_at IS NULL` or the time window
    -- from the live check would leave it passing -- "a case catches a weakening only if the
    -- weakened rule admits the row". These two rows exist and must still be refused.
    INSERT INTO iam.approval_delegations
        (tenant_id, delegation_id, from_identity_id, to_identity_id, starts_at, ends_at,
         reason, created_by, create_correlation_id, revoked_at, revoked_by, revoke_reason,
         revoke_correlation_id)
    VALUES ('11111111-1111-4111-8111-111111111111',
            'dddddddd-0000-4000-8000-000000000001',
            'eeeeeeee-0000-4000-8000-00000000000e',
            'eeeeeeee-0000-4000-8000-00000000000c',
            now() - interval '1 hour', now() + interval '7 days', 'withdrawn',
            'eeeeeeee-0000-4000-8000-00000000000e',
            '33333333-3333-4333-8333-333333333333',
            now(), 'eeeeeeee-0000-4000-8000-00000000000e', 'came back early',
            '33333333-3333-4333-8333-333333333333');
    BEGIN
        INSERT INTO iam.approval_decisions
            (tenant_id, request_id, decided_by, decision, on_behalf_of)
        VALUES ('11111111-1111-4111-8111-111111111111',
                'ffffffff-0000-4000-8000-000000000004',
                'eeeeeeee-0000-4000-8000-00000000000c', 'approved',
                'eeeeeeee-0000-4000-8000-00000000000e');
        RAISE EXCEPTION
            'CHECK 113 FAILED: a revoked delegation still granted somebody''s authority';
    EXCEPTION
        WHEN raise_exception THEN
            IF sqlerrm LIKE 'CHECK 113 FAILED%' THEN RAISE; END IF;
            IF sqlerrm NOT LIKE '%no live delegation grants it%' THEN
                RAISE EXCEPTION 'CHECK 113 FAILED: revoked case answered by: %', sqlerrm;
            END IF;
            probe := probe + 1;
    END;
    -- Expired rather than revoked: the same branch, the other clause.
    UPDATE iam.approval_delegations
       SET revoked_at = NULL, revoked_by = NULL, revoke_reason = NULL,
           revoke_correlation_id = NULL
     WHERE delegation_id = 'dddddddd-0000-4000-8000-000000000001';
    UPDATE iam.approval_delegations
       SET starts_at = now() - interval '30 days', ends_at = now() - interval '1 day'
     WHERE delegation_id = 'dddddddd-0000-4000-8000-000000000001';
    BEGIN
        INSERT INTO iam.approval_decisions
            (tenant_id, request_id, decided_by, decision, on_behalf_of)
        VALUES ('11111111-1111-4111-8111-111111111111',
                'ffffffff-0000-4000-8000-000000000004',
                'eeeeeeee-0000-4000-8000-00000000000c', 'approved',
                'eeeeeeee-0000-4000-8000-00000000000e');
        RAISE EXCEPTION
            'CHECK 113 FAILED: a delegation that has ended still granted authority';
    EXCEPTION
        WHEN raise_exception THEN
            IF sqlerrm LIKE 'CHECK 113 FAILED%' THEN RAISE; END IF;
            IF sqlerrm NOT LIKE '%no live delegation grants it%' THEN
                RAISE EXCEPTION 'CHECK 113 FAILED: expired case answered by: %', sqlerrm;
            END IF;
            probe := probe + 1;
    END;

    -- ---- the delegation table's own CHECKs, which the trigger probes cannot reach.
    --
    -- **A constraint nobody has broken on purpose is a constraint nobody has tested**, and
    -- the mutation sweep said so: dropping the ninety-day ceiling, the not-self rule and the
    -- revocation attribution all passed a block that probed only the triggers. Each case
    -- names the constraint that refused it, because `check_violation` is the same exception
    -- for every CHECK on a table and counting it proves whichever fires first.
    BEGIN
        INSERT INTO iam.approval_delegations
            (tenant_id, from_identity_id, to_identity_id, starts_at, ends_at, reason,
             created_by, create_correlation_id)
        VALUES ('11111111-1111-4111-8111-111111111111',
                'eeeeeeee-0000-4000-8000-00000000000e',
                -- **To the approver, not the requester.** The requester has already
                -- delegated their own approvals away two probes up, so the transitivity
                -- trigger answers first and this case proves that instead of the ceiling --
                -- a new row refused by a sibling, created by this block's own earlier rows.
                'eeeeeeee-0000-4000-8000-00000000000a',
                now(), now() + interval '200 days', 'the whole season',
                'eeeeeeee-0000-4000-8000-00000000000e',
                '33333333-3333-4333-8333-333333333333');
        RAISE EXCEPTION 'CHECK 113 FAILED: a delegation ran past the ninety-day ceiling';
    EXCEPTION
        WHEN check_violation THEN
            GET STACKED DIAGNOSTICS offender = CONSTRAINT_NAME;
            IF offender <> 'approval_delegations_bounded' THEN
                RAISE EXCEPTION
                    'CHECK 113 FAILED: the long delegation was refused by %, so the '
                    'ceiling proves nothing', offender;
            END IF;
            probe := probe + 1;
    END;
    BEGIN
        INSERT INTO iam.approval_delegations
            (tenant_id, from_identity_id, to_identity_id, starts_at, ends_at, reason,
             created_by, create_correlation_id)
        VALUES ('11111111-1111-4111-8111-111111111111',
                'eeeeeeee-0000-4000-8000-00000000000e',
                'eeeeeeee-0000-4000-8000-00000000000e',
                now(), now() + interval '1 day', 'myself',
                'eeeeeeee-0000-4000-8000-00000000000e',
                '33333333-3333-4333-8333-333333333333');
        RAISE EXCEPTION 'CHECK 113 FAILED: an identity delegated to itself';
    EXCEPTION
        WHEN check_violation THEN
            GET STACKED DIAGNOSTICS offender = CONSTRAINT_NAME;
            IF offender <> 'approval_delegations_not_self' THEN
                RAISE EXCEPTION
                    'CHECK 113 FAILED: the self-delegation was refused by %', offender;
            END IF;
            probe := probe + 1;
    END;
    -- The revocation trio, **blank and NULL**, because `coalesce` is what makes the blank
    -- case bite and a case made of spaces cannot tell the two apart -- MOD-014 and MOD-021
    -- each paid for that once.
    BEGIN
        UPDATE iam.approval_delegations
           SET revoked_at = now(), revoked_by = 'eeeeeeee-0000-4000-8000-00000000000e',
               revoke_reason = E'\t', revoke_correlation_id =
               '33333333-3333-4333-8333-333333333333'
         WHERE delegation_id = 'dddddddd-0000-4000-8000-000000000001';
        RAISE EXCEPTION 'CHECK 113 FAILED: a delegation was revoked with a blank reason';
    EXCEPTION
        WHEN check_violation THEN
            GET STACKED DIAGNOSTICS offender = CONSTRAINT_NAME;
            IF offender <> 'approval_delegations_revocation_attributed' THEN
                RAISE EXCEPTION
                    'CHECK 113 FAILED: the blank reason was refused by %', offender;
            END IF;
            probe := probe + 1;
    END;
    BEGIN
        UPDATE iam.approval_delegations
           SET revoked_at = now(), revoked_by = 'eeeeeeee-0000-4000-8000-00000000000e',
               revoke_reason = NULL, revoke_correlation_id =
               '33333333-3333-4333-8333-333333333333'
         WHERE delegation_id = 'dddddddd-0000-4000-8000-000000000001';
        RAISE EXCEPTION 'CHECK 113 FAILED: a delegation was revoked with no reason at all';
    EXCEPTION
        WHEN check_violation THEN
            GET STACKED DIAGNOSTICS offender = CONSTRAINT_NAME;
            IF offender <> 'approval_delegations_revocation_attributed' THEN
                RAISE EXCEPTION
                    'CHECK 113 FAILED: the null reason was refused by %', offender;
            END IF;
            probe := probe + 1;
    END;

    -- ---- R05's stages: the two triggers `0006` adds, and the tables' own CHECKs.
    --
    -- **A single-stage request has no stage rows at all**, which is the one admissible
    -- absence: a policy with no stages is a single-stage policy whose stage is ordinal 1. So
    -- "ordinal 1 with no rows" has to be permitted and every other ordinal refused, which no
    -- composite key can express -- hence a trigger, and hence a probe for each side.
    -- **Its own request, because a refused insert that stops being refused lands a row.**
    -- Pointed at a request other probes decide, the mutation that disables this branch let
    -- the decision through -- and a *later* probe then hit the one-decision-per-approver
    -- index, so the sweep reported a check other than 113 answering. A probe whose row
    -- survives its own mutation needs a subject nobody else touches.
    INSERT INTO iam.approval_requests
        (tenant_id, request_id, action, resource_type, requested_by, required_approvals,
         separation_of_duties, required_permissions, expires_at)
    VALUES ('11111111-1111-4111-8111-111111111111',
            'ffffffff-0000-4000-8000-000000000011', 'billing.refund.issue', 'invoice',
            'eeeeeeee-0000-4000-8000-000000000002', 1, false,
            ARRAY['billing.refund.approve'], now() + interval '1 day');
    BEGIN
        INSERT INTO iam.approval_decisions
            (tenant_id, request_id, decided_by, decision, stage_ordinal)
        VALUES ('11111111-1111-4111-8111-111111111111',
                'ffffffff-0000-4000-8000-000000000011',
                'eeeeeeee-0000-4000-8000-00000000000a', 'approved', 3);
        RAISE EXCEPTION
            'CHECK 113 FAILED: a decision named stage 3 of a single-stage request';
    EXCEPTION
        WHEN raise_exception THEN
            IF sqlerrm LIKE 'CHECK 113 FAILED%' THEN RAISE; END IF;
            IF sqlerrm NOT LIKE '%a decision about nothing%' THEN
                RAISE EXCEPTION
                    'CHECK 113 FAILED: the phantom stage was refused by something else: %',
                    sqlerrm;
            END IF;
            probe := probe + 1;
    END;

    -- A staged, sequential request: stage 1 needs one holder of the refund approval, stage 2
    -- needs one holder of the export permission. Seeded here rather than in the file's main
    -- seed because every probe below is about this one request.
    INSERT INTO iam.approval_requests
        (tenant_id, request_id, action, resource_type, requested_by, required_approvals,
         separation_of_duties, required_permissions, expires_at, sequential)
    VALUES ('11111111-1111-4111-8111-111111111111',
            'ffffffff-0000-4000-8000-00000000000f', 'billing.refund.issue', 'invoice',
            'eeeeeeee-0000-4000-8000-000000000002', 2, false,
            ARRAY['billing.refund.approve'], now() + interval '1 day', true);
    INSERT INTO iam.approval_request_stages
        (tenant_id, request_id, ordinal, required_permission, required_approvals)
    VALUES ('11111111-1111-4111-8111-111111111111',
            'ffffffff-0000-4000-8000-00000000000f', 1, 'billing.refund.approve', 1),
           ('11111111-1111-4111-8111-111111111111',
            'ffffffff-0000-4000-8000-00000000000f', 2, 'finance.export.run', 1);

    BEGIN
        INSERT INTO iam.approval_decisions
            (tenant_id, request_id, decided_by, decision, stage_ordinal)
        VALUES ('11111111-1111-4111-8111-111111111111',
                'ffffffff-0000-4000-8000-00000000000f',
                'eeeeeeee-0000-4000-8000-00000000000a', 'approved', 7);
        RAISE EXCEPTION 'CHECK 113 FAILED: a decision named a stage the request has not got';
    EXCEPTION
        WHEN raise_exception THEN
            IF sqlerrm LIKE 'CHECK 113 FAILED%' THEN RAISE; END IF;
            IF sqlerrm NOT LIKE '%has no stage%' THEN
                RAISE EXCEPTION
                    'CHECK 113 FAILED: the unknown stage was refused by something else: %',
                    sqlerrm;
            END IF;
            probe := probe + 1;
    END;

    -- **The refusal sequential exists for**: stage 2 before stage 1 has its approval.
    BEGIN
        INSERT INTO iam.approval_decisions
            (tenant_id, request_id, decided_by, decision, stage_ordinal)
        VALUES ('11111111-1111-4111-8111-111111111111',
                'ffffffff-0000-4000-8000-00000000000f',
                'eeeeeeee-0000-4000-8000-00000000000a', 'approved', 2);
        RAISE EXCEPTION 'CHECK 113 FAILED: stage 2 was decided before stage 1';
    EXCEPTION
        WHEN raise_exception THEN
            IF sqlerrm LIKE 'CHECK 113 FAILED%' THEN RAISE; END IF;
            IF sqlerrm NOT LIKE '%is not open%' THEN
                RAISE EXCEPTION
                    'CHECK 113 FAILED: the out-of-order stage was refused by something '
                    'else: %', sqlerrm;
            END IF;
            probe := probe + 1;
    END;

    -- **And the permission, which no refusal probe can see.** Stage 1 is open, so it takes a
    -- decision -- and then stage 2 is open too, by a different person, because the unique
    -- index is one decision per approver per request across every stage. Without this the
    -- trigger could refuse every staged decision and the three refusals above would still
    -- pass, which is the "a guard that refuses too much" shape only a permission probe
    -- catches.
    BEGIN
        INSERT INTO iam.approval_decisions
            (tenant_id, request_id, decided_by, decision, stage_ordinal)
        VALUES ('11111111-1111-4111-8111-111111111111',
                'ffffffff-0000-4000-8000-00000000000f',
                'eeeeeeee-0000-4000-8000-00000000000a', 'approved', 1);
        INSERT INTO iam.approval_decisions
            (tenant_id, request_id, decided_by, decision, stage_ordinal)
        VALUES ('11111111-1111-4111-8111-111111111111',
                'ffffffff-0000-4000-8000-00000000000f',
                'eeeeeeee-0000-4000-8000-00000000000e', 'approved', 2);
        probe := probe + 1;
    EXCEPTION
        WHEN OTHERS THEN
            RAISE EXCEPTION
                'CHECK 113 FAILED: stage 1 and then stage 2, by two people, was refused: %',
                sqlerrm;
    END;

    -- **A parallel request's second stage is open from the start**, which is the whole
    -- difference between the two words R05 names -- and a trigger that refused every
    -- out-of-order decision would pass every refusal probe above while making "parallel"
    -- mean nothing. A permission probe is the only thing that sees a guard refusing too much.
    INSERT INTO iam.approval_requests
        (tenant_id, request_id, action, resource_type, requested_by, required_approvals,
         separation_of_duties, required_permissions, expires_at, sequential)
    VALUES ('11111111-1111-4111-8111-111111111111',
            'ffffffff-0000-4000-8000-000000000010', 'billing.refund.issue', 'invoice',
            'eeeeeeee-0000-4000-8000-000000000002', 2, false,
            ARRAY['billing.refund.approve'], now() + interval '1 day', false);
    INSERT INTO iam.approval_request_stages
        (tenant_id, request_id, ordinal, required_permission, required_approvals)
    VALUES ('11111111-1111-4111-8111-111111111111',
            'ffffffff-0000-4000-8000-000000000010', 1, 'billing.refund.approve', 1),
           ('11111111-1111-4111-8111-111111111111',
            'ffffffff-0000-4000-8000-000000000010', 2, 'finance.export.run', 1);
    BEGIN
        INSERT INTO iam.approval_decisions
            (tenant_id, request_id, decided_by, decision, stage_ordinal)
        VALUES ('11111111-1111-4111-8111-111111111111',
                'ffffffff-0000-4000-8000-000000000010',
                'eeeeeeee-0000-4000-8000-00000000000a', 'approved', 2);
        probe := probe + 1;
    EXCEPTION
        WHEN OTHERS THEN
            RAISE EXCEPTION
                'CHECK 113 FAILED: a parallel second stage was refused before the first: %',
                sqlerrm;
    END;

    -- ---- the two stage tables' own CHECKs, which no trigger probe reaches.
    --
    -- Each names the constraint that refused it, because `check_violation` is the same
    -- exception for every CHECK on a table and counting it proves whichever fires first.
    BEGIN
        INSERT INTO iam.approval_request_stages
            (tenant_id, request_id, ordinal, required_permission, required_approvals)
        VALUES ('11111111-1111-4111-8111-111111111111',
                -- **A permission no other stage of this request uses.** With the ordinal
                -- CHECK dropped the row is otherwise answered by the one-stage-per-permission
                -- rule, so the case would prove the sibling -- which the mutation sweep said
                -- by reporting it as answered by a different check.
                'ffffffff-0000-4000-8000-000000000010', 9, 'authz.role.write', 1);
        RAISE EXCEPTION 'CHECK 113 FAILED: a request stage sat past the declared ceiling';
    EXCEPTION
        WHEN check_violation THEN
            GET STACKED DIAGNOSTICS offender = CONSTRAINT_NAME;
            IF offender <> 'approval_request_stages_ordinal' THEN
                RAISE EXCEPTION 'CHECK 113 FAILED: stage 9 was refused by %', offender;
            END IF;
            probe := probe + 1;
    END;
    BEGIN
        INSERT INTO iam.approval_request_stages
            (tenant_id, request_id, ordinal, required_permission, required_approvals)
        VALUES ('11111111-1111-4111-8111-111111111111',
                'ffffffff-0000-4000-8000-000000000010', 3, 'authz.role.read', 0);
        RAISE EXCEPTION 'CHECK 113 FAILED: a request stage asked for no approvers';
    EXCEPTION
        WHEN check_violation THEN
            GET STACKED DIAGNOSTICS offender = CONSTRAINT_NAME;
            IF offender <> 'approval_request_stages_count' THEN
                RAISE EXCEPTION 'CHECK 113 FAILED: the empty quorum was refused by %',
                                offender;
            END IF;
            probe := probe + 1;
    END;
    BEGIN
        INSERT INTO iam.approval_request_stages
            (tenant_id, request_id, ordinal, required_permission, required_approvals)
        VALUES ('11111111-1111-4111-8111-111111111111',
                'ffffffff-0000-4000-8000-000000000010', 3, 'finance.*', 1);
        RAISE EXCEPTION 'CHECK 113 FAILED: a request stage named a wildcard';
    EXCEPTION
        WHEN check_violation THEN
            GET STACKED DIAGNOSTICS offender = CONSTRAINT_NAME;
            IF offender <> 'approval_request_stages_permission_shape' THEN
                RAISE EXCEPTION 'CHECK 113 FAILED: the wildcard was refused by %', offender;
            END IF;
            probe := probe + 1;
    END;
    -- **One authority is one stage**, which is what stops a quorum being written as two rows
    -- that then disagree about the count -- and the permission in the key is what a
    -- prefix-free primary-key sweep cannot see.
    BEGIN
        INSERT INTO iam.approval_request_stages
            (tenant_id, request_id, ordinal, required_permission, required_approvals)
        VALUES ('11111111-1111-4111-8111-111111111111',
                'ffffffff-0000-4000-8000-000000000010', 3, 'finance.export.run', 1);
        RAISE EXCEPTION 'CHECK 113 FAILED: one authority was two stages of one request';
    EXCEPTION
        WHEN unique_violation THEN
            GET STACKED DIAGNOSTICS offender = CONSTRAINT_NAME;
            IF offender NOT LIKE 'approval_request_stages_tenant_id_request_id_required%' THEN
                RAISE EXCEPTION 'CHECK 113 FAILED: the repeat was refused by %', offender;
            END IF;
            probe := probe + 1;
    END;
    BEGIN
        INSERT INTO iam.approval_request_stages
            (tenant_id, request_id, ordinal, required_permission, required_approvals)
        VALUES ('11111111-1111-4111-8111-111111111111',
                'ffffffff-0000-4000-8000-000000000010', 2, 'authz.role.write', 1);
        RAISE EXCEPTION 'CHECK 113 FAILED: two stages shared one ordinal';
    EXCEPTION
        WHEN unique_violation THEN
            GET STACKED DIAGNOSTICS offender = CONSTRAINT_NAME;
            IF offender <> 'approval_request_stages_pkey' THEN
                RAISE EXCEPTION 'CHECK 113 FAILED: the shared ordinal was refused by %',
                                offender;
            END IF;
            probe := probe + 1;
    END;
    -- The policy side, whose three CHECKs are the same rules one table over. **The policy is
    -- seeded here**, because this block had none: the first version read one with a
    -- `LIMIT 1` subselect, which returned NULL and failed on the not-null rather than on the
    -- constraint under test -- a case refused for the wrong reason, which is what every
    -- `GET STACKED DIAGNOSTICS` in this file exists to catch.
    INSERT INTO iam.approval_policies
        (tenant_id, approval_policy_id, action, threshold_minor, required_permission,
         required_approvals, separation_of_duties, sequential)
    VALUES ('11111111-1111-4111-8111-111111111111',
            'cccccccc-0000-4000-8000-000000000001', 'billing.refund.issue', 0,
            'billing.refund.approve', 1, true, false);
    BEGIN
        INSERT INTO iam.approval_policy_stages
            (tenant_id, approval_policy_id, ordinal, required_permission,
             required_approvals, created_by, create_correlation_id)
        VALUES ('11111111-1111-4111-8111-111111111111',
                'cccccccc-0000-4000-8000-000000000001',
                9, 'finance.export.run', 1,
                'eeeeeeee-0000-4000-8000-00000000000e',
                '33333333-3333-4333-8333-333333333333');
        RAISE EXCEPTION 'CHECK 113 FAILED: a policy stage sat past the declared ceiling';
    EXCEPTION
        WHEN check_violation THEN
            GET STACKED DIAGNOSTICS offender = CONSTRAINT_NAME;
            IF offender <> 'approval_policy_stages_ordinal' THEN
                RAISE EXCEPTION 'CHECK 113 FAILED: policy stage 9 was refused by %', offender;
            END IF;
            probe := probe + 1;
    END;
    BEGIN
        INSERT INTO iam.approval_policy_stages
            (tenant_id, approval_policy_id, ordinal, required_permission,
             required_approvals, created_by, create_correlation_id)
        VALUES ('11111111-1111-4111-8111-111111111111',
                'cccccccc-0000-4000-8000-000000000001',
                2, 'finance.export.run', 0,
                'eeeeeeee-0000-4000-8000-00000000000e',
                '33333333-3333-4333-8333-333333333333');
        RAISE EXCEPTION 'CHECK 113 FAILED: a policy stage asked for no approvers';
    EXCEPTION
        WHEN check_violation THEN
            GET STACKED DIAGNOSTICS offender = CONSTRAINT_NAME;
            IF offender <> 'approval_policy_stages_count' THEN
                RAISE EXCEPTION 'CHECK 113 FAILED: the empty policy quorum was refused by %',
                                offender;
            END IF;
            probe := probe + 1;
    END;
    BEGIN
        INSERT INTO iam.approval_policy_stages
            (tenant_id, approval_policy_id, ordinal, required_permission,
             required_approvals, created_by, create_correlation_id)
        VALUES ('11111111-1111-4111-8111-111111111111',
                'cccccccc-0000-4000-8000-000000000001',
                2, 'finance.*', 1,
                'eeeeeeee-0000-4000-8000-00000000000e',
                '33333333-3333-4333-8333-333333333333');
        RAISE EXCEPTION 'CHECK 113 FAILED: a policy stage named a wildcard';
    EXCEPTION
        WHEN check_violation THEN
            GET STACKED DIAGNOSTICS offender = CONSTRAINT_NAME;
            IF offender <> 'approval_policy_stages_permission_shape' THEN
                RAISE EXCEPTION 'CHECK 113 FAILED: the policy wildcard was refused by %',
                                offender;
            END IF;
            probe := probe + 1;
    END;
    IF probe <> 26 THEN
        RAISE EXCEPTION 'CHECK 113 FAILED: ran % of 26 INV-AUT-02 probes', probe;
    END IF;

    -- **And the probe count is compared against the catalogue**, so a refusal added later
    -- without a probe fails here rather than at the next sweep. Counting `RAISE EXCEPTION`
    -- in the module's own trigger functions is the structural half this file applies to
    -- MOD-022's forty-four branches.
    IF (SELECT sum((length(prosrc) - length(replace(prosrc, 'RAISE EXCEPTION', '')))
                   / length('RAISE EXCEPTION'))
          FROM pg_proc
         WHERE pronamespace = 'iam'::regnamespace
           AND proname LIKE 'approval\_%') <> 8 THEN
        RAISE EXCEPTION
            'CHECK 113 FAILED: the approval trigger functions raise a different number of '
            'refusals than this block probes; a branch was added or removed without one';
    END IF;

    -- ---- and the function itself, which `md5(prosrc)` cannot see.
    --
    -- Nothing in this file had ever read `proconfig`, `prosecdef` or `tgenabled` for `iam`:
    -- those sweeps were written for `plt01` modules, and this is the first trigger function
    -- the identity plane has ever had. A reset `search_path`, a `SECURITY DEFINER`, a PUBLIC
    -- execute grant or a disabled trigger each defeat it while leaving the definition intact.
    IF (SELECT proconfig FROM pg_proc
         WHERE oid = 'iam.approval_decider_is_not_the_requester()'::regprocedure)
        IS DISTINCT FROM ARRAY['search_path=pg_catalog, pg_temp'] THEN
        RAISE EXCEPTION 'CHECK 113 FAILED: the trigger function has no pinned search_path';
    END IF;
    IF (SELECT prosecdef FROM pg_proc
         WHERE oid = 'iam.approval_decider_is_not_the_requester()'::regprocedure) THEN
        RAISE EXCEPTION 'CHECK 113 FAILED: the trigger function is SECURITY DEFINER';
    END IF;
    IF has_function_privilege('public', 'iam.approval_decider_is_not_the_requester()',
                              'EXECUTE') THEN
        RAISE EXCEPTION 'CHECK 113 FAILED: PUBLIC may execute the trigger function';
    END IF;
    IF (SELECT tgenabled FROM pg_trigger
         WHERE tgrelid = 'iam.approval_decisions'::regclass
           AND tgname = 'approval_decisions_decider_is_not_the_requester') <> 'O' THEN
        RAISE EXCEPTION 'CHECK 113 FAILED: the trigger is disabled';
    END IF;
END $$;
ROLLBACK;

-- ========================================================= CHECK 114 (MOD-026)
--
-- The module's five trigger functions, branch by branch.
--
-- CHECK 112 pins this module's structure -- the grants, the NOT NULLs, the foreign keys --
-- and a plpgsql branch is invisible to all of it: a generated `ALTER TABLE` sweep touches
-- nothing in `pg_proc`, and a definition pin over `md5(prosrc)` says a body changed without
-- saying whether it still bites. MOD-018 paid for exactly that, where a reviewer deleted the
-- balance trigger's mixed-currency branch and the suite reported 84/84. So MOD-026 shipped
-- eleven refusals with no isolating probe behind any of them, which is "a constraint nobody
-- has broken on purpose is a constraint nobody has tested" one layer in. Two of the eleven
-- turned out to have no case *available* -- every row reaching them is already refused by a
-- sibling CHECK or by the composite foreign key -- and `0023` deletes those rather than
-- testing them harder, which is MOD-016's judgement for a constraint subsumed by a sibling.
--
-- Each probe asserts **the sentence**, not the exception class. These functions are BEFORE
-- triggers, so they fire ahead of every CHECK and every foreign key on the table, and three
-- of the eleven guard a lookup that the key beside them would also refuse -- MOD-021's three
-- `NOT EXISTS` branches, where the branch above answered for the branch below and all three
-- were droppable in silence.
--
-- And the count is compared against the catalogue rather than against itself, so a refusal
-- added later with no probe fails here instead of at the next sweep.
--
-- **Run as the table owner, not as the service's role**, which took one failed run to
-- learn. `target_seconds` and `started_at` are outside every runtime role's UPDATE grant --
-- deliberately, because the trigger refuses them and the grant means it never has to -- so
-- under `veyro_cp_app` the branch that refuses a re-measured promise is answered by the
-- privilege layer and has no evidence of its own. The writer that branch exists for is the
-- owner, and a trigger that refuses the owner refuses everybody; FORCE RLS still applies
-- here, so the tenant predicate is in force too.
BEGIN;
SET LOCAL ROLE veyro_cp_migrator;
SET LOCAL app.tenant_id = '11111111-1111-4111-8111-111111111111';
DO $$
DECLARE
    probe integer := 0;
    cases integer := 0;
    offender text;
    declared integer;
    t constant uuid := '11111111-1111-4111-8111-111111111111';
    loc constant uuid := 'eeeeeeee-1000-4000-8000-000000000001';
    actor constant uuid := 'eeeeeeee-0000-4000-8000-000000000001';
    qa uuid; qb uuid; dead uuid;
    open_case uuid; shut_case uuid;
    task uuid; settled uuid;
    clock uuid;
BEGIN
    -- ---- the fixture, built through the schema rather than assumed.
    INSERT INTO plt01.tsk_queues (tenant_id, queue_key, display_name, location_id,
                                  created_by, create_correlation_id)
    VALUES (t, 'p114a', 'Front desk', loc, actor, gen_random_uuid()) RETURNING queue_id
      INTO qa;
    INSERT INTO plt01.tsk_queues (tenant_id, queue_key, display_name, location_id,
                                  created_by, create_correlation_id)
    VALUES (t, 'p114b', 'Back office', loc, actor, gen_random_uuid()) RETURNING queue_id
      INTO qb;
    INSERT INTO plt01.tsk_queues (tenant_id, queue_key, display_name, location_id,
                                  created_by, create_correlation_id)
    VALUES (t, 'p114d', 'Merged away', loc, actor, gen_random_uuid()) RETURNING queue_id
      INTO dead;
    UPDATE plt01.tsk_queues SET status = 'retired', retired_at = now(), retired_by = actor,
           retire_reason = 'merged into the back office',
           retire_correlation_id = gen_random_uuid()
     WHERE queue_id = dead;

    INSERT INTO plt01.tsk_cases (tenant_id, case_number, title, queue_id, subject_kind,
                                 source, opened_by, open_correlation_id, idempotency_key)
    VALUES (t, 'P114-OPEN', 'Card not working', qa, 'tenant', 'manual', actor,
            gen_random_uuid(), 'p114-open') RETURNING case_id INTO open_case;
    INSERT INTO plt01.tsk_cases (tenant_id, case_number, title, queue_id, subject_kind,
                                 source, opened_by, open_correlation_id, idempotency_key)
    VALUES (t, 'P114-SHUT', 'Settled last month', qa, 'tenant', 'automation', actor,
            gen_random_uuid(), 'p114-shut') RETURNING case_id INTO shut_case;
    UPDATE plt01.tsk_cases SET status = 'resolved', resolved_at = now(),
           resolved_by = actor, resolution_reason = 'replaced the card',
           resolve_correlation_id = gen_random_uuid()
     WHERE case_id = shut_case;
    UPDATE plt01.tsk_cases SET status = 'closed' WHERE case_id = shut_case;

    INSERT INTO plt01.tsk_tasks (tenant_id, queue_id, title, subject_kind, source,
                                 created_by, create_correlation_id, idempotency_key)
    VALUES (t, qa, 'Call the member', 'tenant', 'manual', actor, gen_random_uuid(),
            'p114-task')
    RETURNING task_id INTO task;
    INSERT INTO plt01.tsk_tasks (tenant_id, queue_id, title, subject_kind, source,
                                 created_by, create_correlation_id, idempotency_key)
    VALUES (t, qa, 'Already done', 'tenant', 'ai', actor, gen_random_uuid(), 'p114-settled')
    RETURNING task_id INTO settled;
    UPDATE plt01.tsk_tasks SET status = 'done', settled_at = now(), settled_by = actor,
           settle_reason = 'spoke to them', settle_correlation_id = gen_random_uuid()
     WHERE task_id = settled;

    -- ---- tsk_task_matches_its_case, branch 1 (`0023`): a task filed under a different
    -- queue from its case. The missing-case branch above it is gone -- it duplicated the
    -- composite foreign key, which refuses that row in this tenant and in any other, so it
    -- had no case only it could answer. See `0023`.
    BEGIN
        INSERT INTO plt01.tsk_tasks (tenant_id, queue_id, case_id, title, subject_kind,
                                     source, created_by, create_correlation_id,
                                     idempotency_key)
        VALUES (t, qb, open_case, 'In the wrong backlog', 'tenant', 'manual', actor,
                gen_random_uuid(), 'p114-2');
        RAISE EXCEPTION 'CHECK 114 FAILED: one piece of work was counted in two backlogs';
    EXCEPTION WHEN raise_exception THEN
        IF sqlerrm LIKE 'CHECK 114 FAILED%' THEN RAISE; END IF;
        IF sqlerrm NOT LIKE '%different queue from its case%' THEN
            RAISE EXCEPTION 'CHECK 114 FAILED: refused by something else: %', sqlerrm;
        END IF;
        probe := probe + 1;
    END;

    -- ---- branch 2: a new task on a closed case is work nobody will see.
    BEGIN
        INSERT INTO plt01.tsk_tasks (tenant_id, queue_id, case_id, title, subject_kind,
                                     source, created_by, create_correlation_id,
                                     idempotency_key)
        VALUES (t, qa, shut_case, 'Too late', 'tenant', 'manual', actor, gen_random_uuid(),
                'p114-3');
        RAISE EXCEPTION 'CHECK 114 FAILED: a task was added to a closed case';
    EXCEPTION WHEN raise_exception THEN
        IF sqlerrm LIKE 'CHECK 114 FAILED%' THEN RAISE; END IF;
        IF sqlerrm NOT LIKE '%case is closed%' THEN
            RAISE EXCEPTION 'CHECK 114 FAILED: refused by something else: %', sqlerrm;
        END IF;
        probe := probe + 1;
    END;

    -- ---- tsk_settlement_is_final, branch 1: the attribution does not move.
    BEGIN
        UPDATE plt01.tsk_tasks SET settle_reason = 'something else entirely'
         WHERE task_id = settled;
        RAISE EXCEPTION 'CHECK 114 FAILED: a settled task''s reason was rewritten';
    EXCEPTION WHEN raise_exception THEN
        IF sqlerrm LIKE 'CHECK 114 FAILED%' THEN RAISE; END IF;
        IF sqlerrm NOT LIKE '%already settled%' THEN
            RAISE EXCEPTION 'CHECK 114 FAILED: refused by something else: %', sqlerrm;
        END IF;
        probe := probe + 1;
    END;

    -- ---- tsk_case_resolution_is_final, branch 1: a case moves forward only.
    --
    -- **Closed to *resolved*, not closed to open.** Both statuses satisfy
    -- `tsk_cases_resolution_attributed`, so the trigger is the only thing in the way; going
    -- back to `open` needs the four resolution columns NULL, which the CHECK refuses first
    -- and the probe would then prove the CHECK. The companion-column discipline CHECK 110 is
    -- built on, in the direction where the companion is a *status* rather than a column.
    BEGIN
        UPDATE plt01.tsk_cases SET status = 'resolved' WHERE case_id = shut_case;
        RAISE EXCEPTION 'CHECK 114 FAILED: a closed case went back to resolved';
    EXCEPTION WHEN raise_exception THEN
        IF sqlerrm LIKE 'CHECK 114 FAILED%' THEN RAISE; END IF;
        IF sqlerrm NOT LIKE '%not back%' THEN
            RAISE EXCEPTION 'CHECK 114 FAILED: refused by something else: %', sqlerrm;
        END IF;
        probe := probe + 1;
    END;

    -- ---- branch 2: who resolved it, when and why do not move.
    BEGIN
        UPDATE plt01.tsk_cases SET resolution_reason = 'a different story'
         WHERE case_id = shut_case;
        RAISE EXCEPTION 'CHECK 114 FAILED: a resolved case''s reason was rewritten';
    EXCEPTION WHEN raise_exception THEN
        IF sqlerrm LIKE 'CHECK 114 FAILED%' THEN RAISE; END IF;
        IF sqlerrm NOT LIKE '%already resolved%' THEN
            RAISE EXCEPTION 'CHECK 114 FAILED: refused by something else: %', sqlerrm;
        END IF;
        probe := probe + 1;
    END;

    -- ---- tsk_sla_escalation_is_live: a route may not be pointed at a dead bell.
    BEGIN
        INSERT INTO plt01.tsk_sla_clocks (tenant_id, task_id, location_id, target_seconds,
                                          escalate_to_queue_id, started_at, created_by,
                                          create_correlation_id)
        VALUES (t, task, loc, 3600, dead, now(), actor, gen_random_uuid());
        RAISE EXCEPTION 'CHECK 114 FAILED: a clock escalates to a retired queue';
    EXCEPTION WHEN raise_exception THEN
        IF sqlerrm LIKE 'CHECK 114 FAILED%' THEN RAISE; END IF;
        IF sqlerrm NOT LIKE '%bell nobody answers%' THEN
            RAISE EXCEPTION 'CHECK 114 FAILED: refused by something else: %', sqlerrm;
        END IF;
        probe := probe + 1;
    END;

    -- ---- and the permission `0022` restored, which no refusal probe can see.
    --
    -- The trigger is BEFORE INSERT **OR UPDATE** and re-judged the route on every write, so
    -- retiring a queue refused every later update to every clock pointing at it -- the
    -- settlement included, which is the one write that makes the record true. A guard that
    -- admits a state nothing can leave is worse than no guard. Written as a bare statement
    -- this would abort the block under the trigger's own message, which a sweep cannot tell
    -- from an unrelated error: a probe proving a permission needs a handler exactly as much
    -- as one proving a refusal.
    INSERT INTO plt01.tsk_sla_clocks (tenant_id, task_id, location_id, target_seconds,
                                      escalate_to_queue_id, started_at, created_by,
                                      create_correlation_id)
    VALUES (t, task, loc, 3600, qb, now(), actor, gen_random_uuid())
    RETURNING clock_id INTO clock;
    UPDATE plt01.tsk_queues SET status = 'retired', retired_at = now(), retired_by = actor,
           retire_reason = 'merged after the clock started',
           retire_correlation_id = gen_random_uuid()
     WHERE queue_id = qb;
    BEGIN
        UPDATE plt01.tsk_sla_clocks
           SET status = 'breached', settled_at = now(), settled_by = actor,
               settle_reason = 'the target had gone',
               settle_correlation_id = gen_random_uuid()
         WHERE clock_id = clock;
        probe := probe + 1;
    EXCEPTION WHEN OTHERS THEN
        RAISE EXCEPTION
            'CHECK 114 FAILED: retiring the escalation queue froze the clock pointing at '
            'it, so a missed target can never be judged: %', sqlerrm;
    END;

    -- ---- tsk_sla_settlement_is_final, branch 1: a target is judged once.
    BEGIN
        UPDATE plt01.tsk_sla_clocks SET status = 'met' WHERE clock_id = clock;
        RAISE EXCEPTION 'CHECK 114 FAILED: a settled clock was re-judged';
    EXCEPTION WHEN raise_exception THEN
        IF sqlerrm LIKE 'CHECK 114 FAILED%' THEN RAISE; END IF;
        IF sqlerrm NOT LIKE '%judged once%' THEN
            RAISE EXCEPTION 'CHECK 114 FAILED: refused by something else: %', sqlerrm;
        END IF;
        probe := probe + 1;
    END;

    -- ---- branch 2: who settled it, when and why do not move.
    BEGIN
        UPDATE plt01.tsk_sla_clocks SET settle_reason = 'it was fine really'
         WHERE clock_id = clock;
        RAISE EXCEPTION 'CHECK 114 FAILED: a settled clock''s reason was rewritten';
    EXCEPTION WHEN raise_exception THEN
        IF sqlerrm LIKE 'CHECK 114 FAILED%' THEN RAISE; END IF;
        IF sqlerrm NOT LIKE '%do not move once it is settled%' THEN
            RAISE EXCEPTION 'CHECK 114 FAILED: refused by something else: %', sqlerrm;
        END IF;
        probe := probe + 1;
    END;

    -- ---- branch 3: a target and its start do not move.
    --
    -- Re-measuring a promise after the fact is how a missed one becomes a met one, and this
    -- branch fires on a running clock as well as a settled one -- so the probe uses a fresh
    -- one, leaving the settled row to prove the two branches above it.
    INSERT INTO plt01.tsk_sla_clocks (tenant_id, case_id, location_id, target_seconds,
                                      started_at, created_by, create_correlation_id)
    VALUES (t, open_case, loc, 3600, now(), actor, gen_random_uuid())
    RETURNING clock_id INTO clock;
    BEGIN
        UPDATE plt01.tsk_sla_clocks SET target_seconds = 86400 WHERE clock_id = clock;
        RAISE EXCEPTION 'CHECK 114 FAILED: a target was re-measured after the fact';
    EXCEPTION WHEN raise_exception THEN
        IF sqlerrm LIKE 'CHECK 114 FAILED%' THEN RAISE; END IF;
        IF sqlerrm NOT LIKE '%do not move%' THEN
            RAISE EXCEPTION 'CHECK 114 FAILED: refused by something else: %', sqlerrm;
        END IF;
        probe := probe + 1;
    WHEN insufficient_privilege THEN
        -- Named rather than counted: a probe answered by the privilege layer proves the
        -- grant and says nothing about the trigger, which is why this block runs as the
        -- owner in the first place.
        RAISE EXCEPTION
            'CHECK 114 FAILED: target_seconds was refused by the grant rather than by the '
            'trigger, so that branch has no evidence: %', sqlerrm;
    END;

    -- ---- `0024`'s constraints, each case naming the constraint that refused it.
    --
    -- **`GET STACKED DIAGNOSTICS`, because `check_violation` is the same exception for every
    -- CHECK on a table.** A case that counts the class proves whichever rule fires first --
    -- the trap this repository has shipped in five modules and found by sweeping afterwards
    -- each time. Here it is cheap: the fixture rows above are valid, so each case moves one
    -- field and the companion columns its siblings demand.

    -- A source outside the three the canvas names. ADM-TSK-01: "the source is always named
    -- -- a task nobody can account for gets ignored", so a fourth value is not a new kind of
    -- work, it is a row nobody can file.
    BEGIN
        UPDATE plt01.tsk_tasks SET source = 'telepathy' WHERE task_id = task;
        RAISE EXCEPTION 'CHECK 114 FAILED: a task carries a source nobody declared';
    EXCEPTION
        WHEN check_violation THEN
            GET STACKED DIAGNOSTICS offender = CONSTRAINT_NAME;
            IF offender <> 'tsk_tasks_source' THEN
                RAISE EXCEPTION 'CHECK 114 FAILED: answered by %', offender;
            END IF;
            cases := cases + 1;
        WHEN insufficient_privilege THEN
            -- The point of the column being outside every UPDATE grant. Proved as a
            -- permission rather than counted as a constraint case.
            cases := cases + 1;
    END;

    BEGIN
        UPDATE plt01.tsk_cases SET source = 'telepathy' WHERE case_id = open_case;
        RAISE EXCEPTION 'CHECK 114 FAILED: a case carries a source nobody declared';
    EXCEPTION
        WHEN check_violation THEN
            GET STACKED DIAGNOSTICS offender = CONSTRAINT_NAME;
            IF offender <> 'tsk_cases_source' THEN
                RAISE EXCEPTION 'CHECK 114 FAILED: answered by %', offender;
            END IF;
            cases := cases + 1;
        WHEN insufficient_privilege THEN
            cases := cases + 1;
    END;

    -- A snooze with no account of why. The canvas: "an exception cannot be dismissed, only
    -- deferred with an account of why."
    BEGIN
        UPDATE plt01.tsk_cases
           SET snoozed_at = now(), snoozed_until = now() + interval '3 days',
               snoozed_by = actor, snooze_correlation_id = gen_random_uuid()
         WHERE case_id = open_case;
        RAISE EXCEPTION 'CHECK 114 FAILED: a case was deferred with no stated reason';
    EXCEPTION WHEN check_violation THEN
        GET STACKED DIAGNOSTICS offender = CONSTRAINT_NAME;
        IF offender <> 'tsk_cases_snooze_attributed' THEN
            RAISE EXCEPTION 'CHECK 114 FAILED: answered by %', offender;
        END IF;
        cases := cases + 1;
    END;

    -- A single tab, not two spaces: `btrim` strips spaces and nothing else, which is why
    -- every "states a reason" control in this build is `~ '[^[:space:]]'` and why a
    -- space-only case cannot tell the two forms apart.
    BEGIN
        UPDATE plt01.tsk_cases
           SET snoozed_at = now(), snoozed_until = now() + interval '3 days',
               snooze_reason = E'\t', snoozed_by = actor,
               snooze_correlation_id = gen_random_uuid()
         WHERE case_id = open_case;
        RAISE EXCEPTION 'CHECK 114 FAILED: a tab counted as an account of why';
    EXCEPTION WHEN check_violation THEN
        GET STACKED DIAGNOSTICS offender = CONSTRAINT_NAME;
        IF offender <> 'tsk_cases_snooze_attributed' THEN
            RAISE EXCEPTION 'CHECK 114 FAILED: answered by %', offender;
        END IF;
        cases := cases + 1;
    END;

    -- And the NULL case, which is what proves the `coalesce`. MOD-014 shipped three of these
    -- removable because every case sent a blank string and none sent NULL.
    BEGIN
        UPDATE plt01.tsk_cases
           SET snoozed_at = now(), snoozed_until = now() + interval '3 days',
               snooze_reason = NULL, snoozed_by = actor,
               snooze_correlation_id = gen_random_uuid()
         WHERE case_id = open_case;
        RAISE EXCEPTION 'CHECK 114 FAILED: a NULL reason passed the coalesce';
    EXCEPTION WHEN check_violation THEN
        GET STACKED DIAGNOSTICS offender = CONSTRAINT_NAME;
        IF offender <> 'tsk_cases_snooze_attributed' THEN
            RAISE EXCEPTION 'CHECK 114 FAILED: answered by %', offender;
        END IF;
        cases := cases + 1;
    END;

    -- A deferral stamped in the future: the bound that stops `snoozed_until` being measured
    -- between two values the same writer supplies, which is MOD-021's parked unlock.
    BEGIN
        UPDATE plt01.tsk_cases
           SET snoozed_at = now() + interval '2 days',
               snoozed_until = now() + interval '3 days',
               snooze_reason = 'waiting on the member', snoozed_by = actor,
               snooze_correlation_id = gen_random_uuid()
         WHERE case_id = open_case;
        RAISE EXCEPTION 'CHECK 114 FAILED: a deferral was stamped in the future';
    EXCEPTION WHEN check_violation THEN
        GET STACKED DIAGNOSTICS offender = CONSTRAINT_NAME;
        IF offender <> 'tsk_cases_snooze_not_in_the_future' THEN
            RAISE EXCEPTION 'CHECK 114 FAILED: answered by %', offender;
        END IF;
        cases := cases + 1;
    END;

    -- Both sides of the window, because a case catches a weakening only if the weakened
    -- constraint admits the row: a return date before the deferral, and one beyond a year.
    BEGIN
        UPDATE plt01.tsk_cases
           SET snoozed_at = now(), snoozed_until = now() - interval '1 day',
               snooze_reason = 'waiting on the member', snoozed_by = actor,
               snooze_correlation_id = gen_random_uuid()
         WHERE case_id = open_case;
        RAISE EXCEPTION 'CHECK 114 FAILED: a case returns before it was deferred';
    EXCEPTION WHEN check_violation THEN
        GET STACKED DIAGNOSTICS offender = CONSTRAINT_NAME;
        IF offender <> 'tsk_cases_snooze_is_bounded' THEN
            RAISE EXCEPTION 'CHECK 114 FAILED: answered by %', offender;
        END IF;
        cases := cases + 1;
    END;
    BEGIN
        UPDATE plt01.tsk_cases
           SET snoozed_at = now(), snoozed_until = now() + interval '400 days',
               snooze_reason = 'waiting on the member', snoozed_by = actor,
               snooze_correlation_id = gen_random_uuid()
         WHERE case_id = open_case;
        RAISE EXCEPTION 'CHECK 114 FAILED: a deferral past a year is a dismissal';
    EXCEPTION WHEN check_violation THEN
        GET STACKED DIAGNOSTICS offender = CONSTRAINT_NAME;
        IF offender <> 'tsk_cases_snooze_is_bounded' THEN
            RAISE EXCEPTION 'CHECK 114 FAILED: answered by %', offender;
        END IF;
        cases := cases + 1;
    END;

    -- A resolved case is not deferred: the two say opposite things about whether anybody
    -- still has to look. `shut_case` is closed and carries its resolution, so the only rule
    -- in the way is this one.
    BEGIN
        UPDATE plt01.tsk_cases
           SET snoozed_at = now(), snoozed_until = now() + interval '3 days',
               snooze_reason = 'waiting on the member', snoozed_by = actor,
               snooze_correlation_id = gen_random_uuid()
         WHERE case_id = shut_case;
        RAISE EXCEPTION 'CHECK 114 FAILED: a closed case was deferred';
    EXCEPTION WHEN check_violation THEN
        GET STACKED DIAGNOSTICS offender = CONSTRAINT_NAME;
        IF offender <> 'tsk_cases_snooze_is_not_a_resolution' THEN
            RAISE EXCEPTION 'CHECK 114 FAILED: answered by %', offender;
        END IF;
        cases := cases + 1;
    END;

    -- An affected record of a kind the vocabulary does not carry. `tenant` is deliberately
    -- out of it: an affected record is a specific thing, and a case about the tenant is
    -- about the row's own `tenant_id`, which RLS already bounds.
    BEGIN
        INSERT INTO plt01.tsk_case_affected (tenant_id, case_id, affected_kind, affected_id,
                                             added_by, correlation_id)
        VALUES (t, open_case, 'tenant', gen_random_uuid(), actor, gen_random_uuid());
        RAISE EXCEPTION 'CHECK 114 FAILED: an affected record names no specific thing';
    EXCEPTION WHEN check_violation THEN
        GET STACKED DIAGNOSTICS offender = CONSTRAINT_NAME;
        IF offender <> 'tsk_case_affected_kind' THEN
            RAISE EXCEPTION 'CHECK 114 FAILED: answered by %', offender;
        END IF;
        cases := cases + 1;
    END;

    -- The same member twice, which is what the subject being in the key refuses -- and that
    -- is the figure the sheet's header states and a batch action is sized by.
    INSERT INTO plt01.tsk_case_affected (tenant_id, case_id, affected_kind, affected_id,
                                         added_by, correlation_id)
    VALUES (t, open_case, 'member', 'cccccccc-0000-4000-8000-00000000000a', actor,
            gen_random_uuid());
    -- **The second one carries its own `added_at`, which took a sweep to learn.** `now()` is
    -- the transaction timestamp, so two defaulted inserts inside this block share an instant
    -- -- and a key weakened by *adding* `added_at` would still refuse them, so the case
    -- passed while the weakening was admitted in real life, where the two requests are
    -- seconds apart. A case catches a weakening only if the weakened constraint admits the
    -- row, and here the row had to be made admissible by hand.
    BEGIN
        INSERT INTO plt01.tsk_case_affected (tenant_id, case_id, affected_kind, affected_id,
                                             added_at, added_by, correlation_id)
        VALUES (t, open_case, 'member', 'cccccccc-0000-4000-8000-00000000000a',
                now() + interval '1 second', actor, gen_random_uuid());
        RAISE EXCEPTION 'CHECK 114 FAILED: one member was counted twice on one exception';
    EXCEPTION WHEN unique_violation THEN
        GET STACKED DIAGNOSTICS offender = CONSTRAINT_NAME;
        IF offender <> 'tsk_case_affected_pkey' THEN
            RAISE EXCEPTION 'CHECK 114 FAILED: answered by %', offender;
        END IF;
        cases := cases + 1;
    END;

    -- A withdrawal with nobody's name on it. Adding a record is routine, so the remedy has
    -- to exist and has to be accounted for.
    BEGIN
        UPDATE plt01.tsk_case_affected SET withdrawn_at = now()
         WHERE case_id = open_case;
        RAISE EXCEPTION 'CHECK 114 FAILED: an affected record was withdrawn by nobody';
    EXCEPTION WHEN check_violation THEN
        GET STACKED DIAGNOSTICS offender = CONSTRAINT_NAME;
        IF offender <> 'tsk_case_affected_withdrawal_attributed' THEN
            RAISE EXCEPTION 'CHECK 114 FAILED: answered by %', offender;
        END IF;
        cases := cases + 1;
    END;

    -- A clock started in the future never breaches. MOD-011's unbounded `observed_at` let a
    -- routine caller hold an objective green through an outage still to come.
    BEGIN
        INSERT INTO plt01.tsk_sla_clocks (tenant_id, task_id, location_id, target_seconds,
                                          started_at, created_by, create_correlation_id)
        VALUES (t, task, loc, 3600, now() + interval '2 days', actor, gen_random_uuid());
        RAISE EXCEPTION 'CHECK 114 FAILED: a clock was started in the future';
    EXCEPTION WHEN check_violation THEN
        GET STACKED DIAGNOSTICS offender = CONSTRAINT_NAME;
        IF offender <> 'tsk_sla_clocks_start_not_in_the_future' THEN
            RAISE EXCEPTION 'CHECK 114 FAILED: answered by %', offender;
        END IF;
        cases := cases + 1;
    END;

    -- ---- and the two entry kinds `0024` admits, which no refusal case can see.
    --
    -- A handover and a deferral are neither a note nor a status change, and the canvas makes
    -- both first-class acts with their own accounts. A widening is only provable from the
    -- permitted side.
    BEGIN
        INSERT INTO plt01.tsk_case_entries (tenant_id, case_id, entry_kind, summary,
                                            recorded_by, correlation_id)
        VALUES (t, open_case, 'assignment', 'handed to the duty manager', actor,
                gen_random_uuid()),
               (t, open_case, 'deferral', 'deferred to Monday, waiting on the member', actor,
                gen_random_uuid());
        cases := cases + 1;
    EXCEPTION WHEN OTHERS THEN
        RAISE EXCEPTION
            'CHECK 114 FAILED: a handover or a deferral cannot be recorded, so the canvas''s '
            'two first-class acts have nowhere to go: %', sqlerrm;
    END;

    IF cases <> 14 THEN
        RAISE EXCEPTION 'CHECK 114 FAILED: ran % of 14 MOD-026 constraint cases', cases;
    END IF;

    IF probe <> 10 THEN
        RAISE EXCEPTION 'CHECK 114 FAILED: ran % of 10 MOD-026 trigger probes', probe;
    END IF;
    SELECT sum((length(prosrc) - length(replace(prosrc, 'RAISE EXCEPTION', '')))
               / length('RAISE EXCEPTION'))
      INTO declared
      FROM pg_proc
     WHERE pronamespace = 'plt01'::regnamespace AND proname LIKE 'tsk\_%';
    -- Nine refusals and ten probes: the extra one is the permission above, which no `RAISE`
    -- can account for and which is the whole of `0022`.
    IF declared <> probe - 1 THEN
        RAISE EXCEPTION
            'CHECK 114 FAILED: MOD-026 trigger functions raise % refusals and this block '
            'probes % of them: a branch was added or removed without its probe',
            declared, probe - 1;
    END IF;
    -- And the properties `md5(prosrc)` cannot see, swept rather than named: nothing in this
    -- file had ever read `proconfig`, `prosecdef` or `tgenabled` until MOD-020's review.
    FOR declared IN
        SELECT 1 FROM pg_proc
         WHERE pronamespace = 'plt01'::regnamespace AND proname LIKE 'tsk\_%'
           AND (proconfig IS DISTINCT FROM ARRAY['search_path=pg_catalog, pg_temp']
                OR prosecdef
                OR has_function_privilege('public', oid, 'EXECUTE'))
    LOOP
        RAISE EXCEPTION
            'CHECK 114 FAILED: a MOD-026 trigger function has no pinned search_path, is '
            'SECURITY DEFINER, or is executable by PUBLIC';
    END LOOP;
    FOR declared IN
        SELECT 1 FROM pg_trigger g JOIN pg_class c ON c.oid = g.tgrelid
         WHERE c.relnamespace = 'plt01'::regnamespace AND c.relname LIKE 'tsk\_%'
           AND NOT g.tgisinternal AND g.tgenabled <> 'O'
    LOOP
        RAISE EXCEPTION 'CHECK 114 FAILED: a MOD-026 trigger is disabled';
    END LOOP;
END $$;
ROLLBACK;

-- ========================================================= CHECK 115 (MOD-027)
--
-- MOD-027 slice 1's own structure and its constraint cases. The prefix-free sweeps prove the
-- schema-wide rules -- RLS, the policy predicate, the tenant foreign key, the tenant-leading
-- key, the privilege bans -- and nothing about *this* module, so what is here is the three
-- pins this file requires per module plus one case per rule that can be isolated.
BEGIN;
DO $$
DECLARE
    wrong text;
BEGIN
    -- ---- the UPDATE grants, per role and per column, both directions.
    --
    -- **Not `person_id`**: re-pointing a lead at another person is the duplicate-entry defect
    -- ADM-CRM-04 is structured against, arriving through an UPDATE. **Not `created_at`**: age
    -- is the column ADM-CRM-02 says matters, and a lead whose age could be reset is a lead
    -- that never goes cold. **Not `source_key`**: a report groups by it, so re-keying one
    -- would silently merge two histories.
    FOR wrong IN
        WITH expected(t, c) AS (VALUES
            ('crm_lead_sources', 'display_name'), ('crm_lead_sources', 'status'),
            ('crm_lead_sources', 'retired_at'), ('crm_lead_sources', 'retired_by'),
            ('crm_lead_sources', 'retire_reason'),
            ('crm_lead_sources', 'retire_correlation_id'),
            ('crm_leads', 'stage'), ('crm_leads', 'stage_changed_at'),
            ('crm_leads', 'source_id'), ('crm_leads', 'owner_person_id'),
            ('crm_leads', 'next_action'), ('crm_leads', 'next_action_on'),
            ('crm_leads', 'version'),
            -- ADR-0010 D8: a loss is recorded and a reopening clears it, so these four move
            -- while the stage they were lost at does not.
            ('crm_leads', 'lost_at'), ('crm_leads', 'lost_reason'),
            ('crm_leads', 'lost_detail'), ('crm_leads', 'lost_by'),
            -- D11: the withdrawal `0027` said slice 3 owed. One way, by trigger.
            ('crm_lead_interests', 'withdrawn_at'),
            ('crm_lead_interests', 'withdrawn_by')),
        actual(role, t, c) AS (
            SELECT r.rolname, cl.relname::text, a.attname::text
              FROM pg_class cl
              JOIN pg_attribute a ON a.attrelid = cl.oid AND a.attnum > 0 AND NOT a.attisdropped
              CROSS JOIN (VALUES ('veyro_cp_app'), ('veyro_cp_worker')) AS rr(rolname)
              JOIN pg_roles r ON r.rolname = rr.rolname
             WHERE cl.relnamespace = 'plt01'::regnamespace
               AND cl.relkind IN ('r', 'p')
               AND cl.relname LIKE 'crm\_%'
               AND has_column_privilege(r.rolname, cl.oid, a.attname, 'UPDATE'))
        SELECT format('%s has UPDATE on %s.%s which is not in the pin', role, t, c)
          FROM actual WHERE (t, c) NOT IN (SELECT t, c FROM expected)
        UNION ALL
        SELECT format('%s.%s is pinned as updatable and no role holds it', t, c)
          FROM expected e
         WHERE NOT EXISTS (SELECT 1 FROM actual a WHERE a.t = e.t AND a.c = e.c)
    LOOP
        RAISE EXCEPTION 'CHECK 115 FAILED: %', wrong;
    END LOOP;

    -- ---- every column, as a set, which this check did not have.
    --
    -- **The sweep found the hole by adding a column and watching nothing object.** CHECK 115
    -- pinned the UPDATE grants, the NOT NULLs, the foreign keys and the unique rules -- and a
    -- *nullable* column with no grant is in none of those, so `ALTER TABLE crm_leads ADD
    -- COLUMN lost_note text` passed all 115 checks. Every other module in this build has a
    -- column-list pin (MOD-017's is CHECK 76) and MOD-027's was missing from the start,
    -- which is this file's own "a per-table list has to be edited when a module adds a table"
    -- one level in: a per-*property* list has to be complete, and this one had four of five.
    FOR wrong IN
        WITH expected(t, cols) AS (VALUES
            ('crm_lead_interests',
             'correlation_id,interest,interest_id,lead_id,recorded_at,recorded_by,'
             'tenant_id,withdrawn_at,withdrawn_by'),
            ('crm_lead_sources',
             'create_correlation_id,created_at,created_by,display_name,location_id,'
             'retire_correlation_id,retire_reason,retired_at,retired_by,source_id,'
             'source_key,status,tenant_id'),
            ('crm_leads',
             'correlation_id,created_at,created_by,lead_id,lost_at,lost_by,lost_detail,'
             'lost_reason,next_action,next_action_on,owner_person_id,person_id,source_id,'
             'stage,stage_changed_at,tenant_id,version'),
            ('crm_touchpoints',
             'correlation_id,kind,lead_id,occurred_at,recorded_at,recorded_by,summary,'
             'tenant_id,touchpoint_id')),
        actual(t, cols) AS (
            SELECT cl.relname::text, string_agg(a.attname, ',' ORDER BY a.attname)
              FROM pg_class cl
              JOIN pg_attribute a ON a.attrelid = cl.oid AND a.attnum > 0
                                 AND NOT a.attisdropped
             WHERE cl.relnamespace = 'plt01'::regnamespace
               AND cl.relkind IN ('r', 'p') AND cl.relname LIKE 'crm\_%'
             GROUP BY cl.relname)
        SELECT format('%s column list differs: pinned %s, found %s', a.t, e.cols, a.cols)
          FROM actual a JOIN expected e ON e.t = a.t WHERE e.cols <> a.cols
        UNION ALL
        SELECT format('%s is a crm_ table the pin does not name', t)
          FROM actual WHERE t NOT IN (SELECT t FROM expected)
        UNION ALL
        SELECT format('%s is pinned and is gone', t)
          FROM expected WHERE t NOT IN (SELECT t FROM actual)
    LOOP
        RAISE EXCEPTION 'CHECK 115 FAILED: %', wrong;
    END LOOP;

    -- ---- every NOT NULL, as a set. A NOT NULL is what makes a sibling CHECK bite, and under
    -- MATCH SIMPLE a NULL in any column of a composite foreign key skips the whole check.
    FOR wrong IN
        WITH expected(t, c) AS (VALUES
            ('crm_lead_sources', 'tenant_id'), ('crm_lead_sources', 'source_id'),
            ('crm_lead_sources', 'source_key'), ('crm_lead_sources', 'display_name'),
            ('crm_lead_sources', 'status'), ('crm_lead_sources', 'created_at'),
            ('crm_lead_sources', 'created_by'),
            ('crm_lead_sources', 'create_correlation_id'),
            ('crm_leads', 'tenant_id'), ('crm_leads', 'lead_id'),
            ('crm_leads', 'person_id'), ('crm_leads', 'stage'),
            ('crm_leads', 'stage_changed_at'), ('crm_leads', 'version'),
            ('crm_leads', 'created_at'), ('crm_leads', 'created_by'),
            ('crm_leads', 'correlation_id'),
            ('crm_lead_interests', 'tenant_id'), ('crm_lead_interests', 'lead_id'),
            ('crm_lead_interests', 'interest_id'),
            ('crm_lead_interests', 'interest'), ('crm_lead_interests', 'recorded_at'),
            ('crm_lead_interests', 'recorded_by'),
            ('crm_lead_interests', 'correlation_id'),
            ('crm_touchpoints', 'tenant_id'), ('crm_touchpoints', 'touchpoint_id'),
            ('crm_touchpoints', 'lead_id'), ('crm_touchpoints', 'kind'),
            ('crm_touchpoints', 'occurred_at'), ('crm_touchpoints', 'summary'),
            ('crm_touchpoints', 'recorded_at'), ('crm_touchpoints', 'recorded_by'),
            ('crm_touchpoints', 'correlation_id')),
        actual(t, c) AS (
            SELECT cl.relname::text, a.attname::text
              FROM pg_class cl
              JOIN pg_attribute a ON a.attrelid = cl.oid AND a.attnum > 0
                                 AND NOT a.attisdropped AND a.attnotnull
             WHERE cl.relnamespace = 'plt01'::regnamespace
               AND cl.relkind IN ('r', 'p') AND cl.relname LIKE 'crm\_%')
        SELECT format('%s.%s is NOT NULL and the pin does not say so', t, c)
          FROM actual WHERE (t, c) NOT IN (SELECT t, c FROM expected)
        UNION ALL
        SELECT format('%s.%s is pinned NOT NULL and is nullable', t, c)
          FROM expected WHERE (t, c) NOT IN (SELECT t, c FROM actual)
    LOOP
        RAISE EXCEPTION 'CHECK 115 FAILED: %', wrong;
    END LOOP;

    -- ---- every foreign key, as a set. MOD-012's lesson: a sweep of one *kind* of reference
    -- is not a sweep, and `owner_person_id` beside `person_id` is exactly the shape that gets
    -- sampled.
    FOR wrong IN
        WITH expected(t, def) AS (VALUES
            ('crm_lead_sources', 'FOREIGN KEY (tenant_id) REFERENCES plt01_platform.tenants(tenant_id)'),
            ('crm_lead_sources', 'FOREIGN KEY (tenant_id, location_id) REFERENCES plt01.locations(tenant_id, location_id)'),
            ('crm_leads', 'FOREIGN KEY (tenant_id) REFERENCES plt01_platform.tenants(tenant_id)'),
            ('crm_leads', 'FOREIGN KEY (tenant_id, person_id) REFERENCES plt01.ppl_persons(tenant_id, person_id)'),
            ('crm_leads', 'FOREIGN KEY (tenant_id, owner_person_id) REFERENCES plt01.ppl_persons(tenant_id, person_id)'),
            ('crm_leads', 'FOREIGN KEY (tenant_id, source_id) REFERENCES plt01.crm_lead_sources(tenant_id, source_id)'),
            ('crm_lead_interests', 'FOREIGN KEY (tenant_id) REFERENCES plt01_platform.tenants(tenant_id)'),
            ('crm_lead_interests', 'FOREIGN KEY (tenant_id, lead_id) REFERENCES plt01.crm_leads(tenant_id, lead_id)'),
            ('crm_touchpoints', 'FOREIGN KEY (tenant_id) REFERENCES plt01_platform.tenants(tenant_id)'),
            ('crm_touchpoints', 'FOREIGN KEY (tenant_id, lead_id) REFERENCES plt01.crm_leads(tenant_id, lead_id)')),
        actual(t, def) AS (
            SELECT cl.relname::text, pg_get_constraintdef(c.oid)
              FROM pg_constraint c
              JOIN pg_class cl ON cl.oid = c.conrelid
             WHERE cl.relnamespace = 'plt01'::regnamespace
               AND cl.relname LIKE 'crm\_%' AND c.contype = 'f')
        SELECT format('%s carries %s which is not pinned', t, def)
          FROM actual WHERE (t, def) NOT IN (SELECT t, def FROM expected)
        UNION ALL
        SELECT format('%s is pinned to carry %s and does not', t, def)
          FROM expected WHERE (t, def) NOT IN (SELECT t, def FROM actual)
    LOOP
        RAISE EXCEPTION 'CHECK 115 FAILED: %', wrong;
    END LOOP;

    -- ---- one unique rule per thing the design says cannot happen twice.
    FOR wrong IN
        WITH expected(name) AS (VALUES
            ('crm_lead_sources_one_key'), ('crm_leads_one_per_person'),
            -- Partial on live rows, because a lead who withdrew PT and asked for it again
            -- would otherwise be refused by the row they withdrew.
            ('crm_lead_interests_one_live')),
        actual(name) AS (
            SELECT ci.relname::text
              FROM pg_index i
              JOIN pg_class ci ON ci.oid = i.indexrelid
              JOIN pg_class ct ON ct.oid = i.indrelid
             WHERE ct.relnamespace = 'plt01'::regnamespace
               AND ct.relname LIKE 'crm\_%' AND i.indisunique AND NOT i.indisprimary)
        SELECT format('%s is a unique rule the pin does not name', name)
          FROM actual WHERE name NOT IN (SELECT name FROM expected)
        UNION ALL
        SELECT format('%s is pinned and is gone', name)
          FROM expected WHERE name NOT IN (SELECT name FROM actual)
    LOOP
        RAISE EXCEPTION 'CHECK 115 FAILED: %', wrong;
    END LOOP;
END $$;
ROLLBACK;

-- ---- the cases.
--
-- Each row is the seed's own valid row with exactly one field moved, and each names the
-- constraint that refused it: `check_violation` is the same exception for every CHECK on a
-- table, so a case that counts it proves whichever fires first -- the trap this repository has
-- shipped in six modules and found by sweeping afterwards each time.
BEGIN;
SET LOCAL ROLE veyro_cp_app;
SET LOCAL app.tenant_id = '11111111-1111-4111-8111-111111111111';

INSERT INTO plt01.crm_lead_sources
    (tenant_id, source_id, source_key, display_name, created_by, create_correlation_id)
VALUES ('11111111-1111-4111-8111-111111111111', 'cccccccc-9000-4000-8000-000000000001',
        'open_day', 'Sweifieh open day', '33333333-3333-4333-8333-333333333333',
        '33333333-3333-4333-8333-333333333333');
INSERT INTO plt01.crm_leads
    (tenant_id, lead_id, person_id, source_id, created_by, correlation_id)
VALUES ('11111111-1111-4111-8111-111111111111', 'cccccccc-9000-4000-8000-000000000002',
        'bbbbbbbb-1000-4000-8000-000000000001', 'cccccccc-9000-4000-8000-000000000001',
        '33333333-3333-4333-8333-333333333333',
        '33333333-3333-4333-8333-333333333333');

DO $$
DECLARE
    offender text;
    probe int := 0;
    wrong text;
    -- The SQLSTATE beside the constraint name: a permission case that comes back
    -- `insufficient_privilege` has no constraint to name, and its message has to say so.
    state text;
BEGIN
    -- A source key that is not a key.
    BEGIN
        INSERT INTO plt01.crm_lead_sources
            (tenant_id, source_key, display_name, created_by, create_correlation_id)
        VALUES ('11111111-1111-4111-8111-111111111111', 'Open Day!', 'Something',
                '33333333-3333-4333-8333-333333333333',
                '33333333-3333-4333-8333-333333333333');
        RAISE EXCEPTION 'CHECK 115 FAILED: a source key that is not a key';
    EXCEPTION
        WHEN check_violation THEN
            GET STACKED DIAGNOSTICS offender = CONSTRAINT_NAME;
            IF offender <> 'crm_lead_sources_key_shape' THEN
                RAISE EXCEPTION 'CHECK 115 FAILED: refused by % instead', offender;
            END IF;
            probe := probe + 1;
    END;

    -- A source with a blank name. The regex form, not `btrim`: a tab is whitespace too, and
    -- 118 constraints in this build were once satisfied by one.
    BEGIN
        INSERT INTO plt01.crm_lead_sources
            (tenant_id, source_key, display_name, created_by, create_correlation_id)
        VALUES ('11111111-1111-4111-8111-111111111111', 'nameless', E'\t',
                '33333333-3333-4333-8333-333333333333',
                '33333333-3333-4333-8333-333333333333');
        RAISE EXCEPTION 'CHECK 115 FAILED: a source with no name';
    EXCEPTION
        WHEN check_violation THEN
            GET STACKED DIAGNOSTICS offender = CONSTRAINT_NAME;
            IF offender <> 'crm_lead_sources_name_stated' THEN
                RAISE EXCEPTION 'CHECK 115 FAILED: refused by % instead', offender;
            END IF;
            probe := probe + 1;
    END;

    -- A source retired with no stated reason. The `coalesce` is what this proves: a CHECK
    -- passes on NULL, so without it the one record of why a source stopped being offered
    -- could be empty -- the trap MOD-014 and MOD-021 each paid for once.
    BEGIN
        UPDATE plt01.crm_lead_sources
           SET status = 'retired', retired_at = now(),
               retired_by = '33333333-3333-4333-8333-333333333333',
               retire_reason = NULL,
               retire_correlation_id = '33333333-3333-4333-8333-333333333333'
         WHERE source_id = 'cccccccc-9000-4000-8000-000000000001';
        RAISE EXCEPTION 'CHECK 115 FAILED: a source retired with no stated reason';
    EXCEPTION
        WHEN check_violation THEN
            GET STACKED DIAGNOSTICS offender = CONSTRAINT_NAME;
            IF offender <> 'crm_lead_sources_retirement_attributed' THEN
                RAISE EXCEPTION 'CHECK 115 FAILED: refused by % instead', offender;
            END IF;
            probe := probe + 1;
    END;

    -- A retired status with no retirement date, which is the other side of the pair: the
    -- attribution constraint admits the all-NULL row, so only this one catches a status that
    -- says retired while the dates say live.
    BEGIN
        UPDATE plt01.crm_lead_sources SET status = 'retired'
         WHERE source_id = 'cccccccc-9000-4000-8000-000000000001';
        RAISE EXCEPTION 'CHECK 115 FAILED: retired with no retirement';
    EXCEPTION
        WHEN check_violation THEN
            GET STACKED DIAGNOSTICS offender = CONSTRAINT_NAME;
            IF offender <> 'crm_lead_sources_retired_is_retired' THEN
                RAISE EXCEPTION 'CHECK 115 FAILED: refused by % instead', offender;
            END IF;
            probe := probe + 1;
    END;

    -- A source status outside the two.
    BEGIN
        UPDATE plt01.crm_lead_sources SET status = 'paused'
         WHERE source_id = 'cccccccc-9000-4000-8000-000000000001';
        RAISE EXCEPTION 'CHECK 115 FAILED: a source status outside the two';
    EXCEPTION
        WHEN check_violation THEN
            GET STACKED DIAGNOSTICS offender = CONSTRAINT_NAME;
            IF offender <> 'crm_lead_sources_status' THEN
                RAISE EXCEPTION 'CHECK 115 FAILED: refused by % instead', offender;
            END IF;
            probe := probe + 1;
    END;

    -- **A second lead for one person**, which is the duplicate ADM-CRM-04 is structured to
    -- prevent and the one rule in this module the service relies on the database for.
    BEGIN
        INSERT INTO plt01.crm_leads
            (tenant_id, person_id, created_by, correlation_id)
        VALUES ('11111111-1111-4111-8111-111111111111',
                'bbbbbbbb-1000-4000-8000-000000000001',
                '33333333-3333-4333-8333-333333333333',
                '33333333-3333-4333-8333-333333333333');
        RAISE EXCEPTION 'CHECK 115 FAILED: a second lead for one person';
    EXCEPTION
        WHEN unique_violation THEN
            GET STACKED DIAGNOSTICS offender = CONSTRAINT_NAME;
            IF offender <> 'crm_leads_one_per_person' THEN
                RAISE EXCEPTION 'CHECK 115 FAILED: refused by % instead', offender;
            END IF;
            probe := probe + 1;
    END;

    -- A stage outside the three this module stores. `lost` is slice 3's and the derived
    -- columns are MOD-017's, so neither is writable here.
    BEGIN
        UPDATE plt01.crm_leads SET stage = 'lost'
         WHERE lead_id = 'cccccccc-9000-4000-8000-000000000002';
        RAISE EXCEPTION 'CHECK 115 FAILED: a stage outside the three';
    EXCEPTION
        WHEN check_violation THEN
            GET STACKED DIAGNOSTICS offender = CONSTRAINT_NAME;
            IF offender <> 'crm_leads_stage' THEN
                RAISE EXCEPTION 'CHECK 115 FAILED: refused by % instead', offender;
            END IF;
            probe := probe + 1;
    END;

    -- A next action with no date, and a date with no action: both sides, because an
    -- implication either way would admit one of them.
    BEGIN
        UPDATE plt01.crm_leads SET next_action = 'call back'
         WHERE lead_id = 'cccccccc-9000-4000-8000-000000000002';
        RAISE EXCEPTION 'CHECK 115 FAILED: a next action with no date';
    EXCEPTION
        WHEN check_violation THEN
            GET STACKED DIAGNOSTICS offender = CONSTRAINT_NAME;
            IF offender <> 'crm_leads_next_action_paired' THEN
                RAISE EXCEPTION 'CHECK 115 FAILED: refused by % instead', offender;
            END IF;
            probe := probe + 1;
    END;
    BEGIN
        UPDATE plt01.crm_leads SET next_action_on = DATE '2026-09-01'
         WHERE lead_id = 'cccccccc-9000-4000-8000-000000000002';
        RAISE EXCEPTION 'CHECK 115 FAILED: a date with no next action';
    EXCEPTION
        WHEN check_violation THEN
            GET STACKED DIAGNOSTICS offender = CONSTRAINT_NAME;
            IF offender <> 'crm_leads_next_action_paired' THEN
                RAISE EXCEPTION 'CHECK 115 FAILED: refused by % instead', offender;
            END IF;
            probe := probe + 1;
    END;

    -- A next action that is whitespace, with its date supplied so the pairing is satisfied
    -- and this is the only rule left to refuse it.
    BEGIN
        UPDATE plt01.crm_leads
           SET next_action = E'\t', next_action_on = DATE '2026-09-01'
         WHERE lead_id = 'cccccccc-9000-4000-8000-000000000002';
        RAISE EXCEPTION 'CHECK 115 FAILED: a blank next action';
    EXCEPTION
        WHEN check_violation THEN
            GET STACKED DIAGNOSTICS offender = CONSTRAINT_NAME;
            IF offender <> 'crm_leads_next_action_stated' THEN
                RAISE EXCEPTION 'CHECK 115 FAILED: refused by % instead', offender;
            END IF;
            probe := probe + 1;
    END;

    -- A next action longer than the column admits.
    BEGIN
        UPDATE plt01.crm_leads
           SET next_action = repeat('x', 201), next_action_on = DATE '2026-09-01'
         WHERE lead_id = 'cccccccc-9000-4000-8000-000000000002';
        RAISE EXCEPTION 'CHECK 115 FAILED: an unbounded next action';
    EXCEPTION
        WHEN check_violation THEN
            GET STACKED DIAGNOSTICS offender = CONSTRAINT_NAME;
            IF offender <> 'crm_leads_next_action_bounded' THEN
                RAISE EXCEPTION 'CHECK 115 FAILED: refused by % instead', offender;
            END IF;
            probe := probe + 1;
    END;

    -- A version below one, which optimistic concurrency reads as a row nobody has written.
    BEGIN
        UPDATE plt01.crm_leads SET version = 0
         WHERE lead_id = 'cccccccc-9000-4000-8000-000000000002';
        RAISE EXCEPTION 'CHECK 115 FAILED: a version below one';
    EXCEPTION
        WHEN check_violation THEN
            GET STACKED DIAGNOSTICS offender = CONSTRAINT_NAME;
            IF offender <> 'crm_leads_version_positive' THEN
                RAISE EXCEPTION 'CHECK 115 FAILED: refused by % instead', offender;
            END IF;
            probe := probe + 1;
    END;

    -- An interest outside the three the canvas offers.
    BEGIN
        INSERT INTO plt01.crm_lead_interests
            (tenant_id, lead_id, interest, recorded_by, correlation_id)
        VALUES ('11111111-1111-4111-8111-111111111111',
                'cccccccc-9000-4000-8000-000000000002', 'nutrition',
                '33333333-3333-4333-8333-333333333333',
                '33333333-3333-4333-8333-333333333333');
        RAISE EXCEPTION 'CHECK 115 FAILED: an interest outside the three';
    EXCEPTION
        WHEN check_violation THEN
            GET STACKED DIAGNOSTICS offender = CONSTRAINT_NAME;
            IF offender <> 'crm_lead_interests_vocabulary' THEN
                RAISE EXCEPTION 'CHECK 115 FAILED: refused by % instead', offender;
            END IF;
            probe := probe + 1;
    END;

    -- A touchpoint of a kind nobody declared.
    BEGIN
        INSERT INTO plt01.crm_touchpoints
            (tenant_id, lead_id, kind, occurred_at, summary, recorded_by, correlation_id)
        VALUES ('11111111-1111-4111-8111-111111111111',
                'cccccccc-9000-4000-8000-000000000002', 'carrier_pigeon', now(),
                'sent a bird', '33333333-3333-4333-8333-333333333333',
                '33333333-3333-4333-8333-333333333333');
        RAISE EXCEPTION 'CHECK 115 FAILED: a touchpoint of an unknown kind';
    EXCEPTION
        WHEN check_violation THEN
            GET STACKED DIAGNOSTICS offender = CONSTRAINT_NAME;
            IF offender <> 'crm_touchpoints_kind' THEN
                RAISE EXCEPTION 'CHECK 115 FAILED: refused by % instead', offender;
            END IF;
            probe := probe + 1;
    END;

    -- A touchpoint with nothing written in it, and one longer than the column admits.
    BEGIN
        INSERT INTO plt01.crm_touchpoints
            (tenant_id, lead_id, kind, occurred_at, summary, recorded_by, correlation_id)
        VALUES ('11111111-1111-4111-8111-111111111111',
                'cccccccc-9000-4000-8000-000000000002', 'note', now(), E'\t',
                '33333333-3333-4333-8333-333333333333',
                '33333333-3333-4333-8333-333333333333');
        RAISE EXCEPTION 'CHECK 115 FAILED: a touchpoint with no summary';
    EXCEPTION
        WHEN check_violation THEN
            GET STACKED DIAGNOSTICS offender = CONSTRAINT_NAME;
            IF offender <> 'crm_touchpoints_summary_stated' THEN
                RAISE EXCEPTION 'CHECK 115 FAILED: refused by % instead', offender;
            END IF;
            probe := probe + 1;
    END;
    BEGIN
        INSERT INTO plt01.crm_touchpoints
            (tenant_id, lead_id, kind, occurred_at, summary, recorded_by, correlation_id)
        VALUES ('11111111-1111-4111-8111-111111111111',
                'cccccccc-9000-4000-8000-000000000002', 'note', now(), repeat('x', 2001),
                '33333333-3333-4333-8333-333333333333',
                '33333333-3333-4333-8333-333333333333');
        RAISE EXCEPTION 'CHECK 115 FAILED: an unbounded touchpoint summary';
    EXCEPTION
        WHEN check_violation THEN
            GET STACKED DIAGNOSTICS offender = CONSTRAINT_NAME;
            IF offender <> 'crm_touchpoints_summary_bounded' THEN
                RAISE EXCEPTION 'CHECK 115 FAILED: refused by % instead', offender;
            END IF;
            probe := probe + 1;
    END;

    -- **A touchpoint in the future**, which is the bound "no contact · 2 days" is counted
    -- from: a note dated forward would make a cold lead read as warm. Measured against the
    -- server's own clock rather than between two columns the same writer supplies, which is
    -- MOD-021's finding.
    BEGIN
        INSERT INTO plt01.crm_touchpoints
            (tenant_id, lead_id, kind, occurred_at, summary, recorded_by, correlation_id)
        VALUES ('11111111-1111-4111-8111-111111111111',
                'cccccccc-9000-4000-8000-000000000002', 'note',
                now() + interval '1 day', 'spoke to her tomorrow',
                '33333333-3333-4333-8333-333333333333',
                '33333333-3333-4333-8333-333333333333');
        RAISE EXCEPTION 'CHECK 115 FAILED: a touchpoint in the future';
    EXCEPTION
        WHEN check_violation THEN
            GET STACKED DIAGNOSTICS offender = CONSTRAINT_NAME;
            IF offender <> 'crm_touchpoints_not_in_the_future' THEN
                RAISE EXCEPTION 'CHECK 115 FAILED: refused by % instead', offender;
            END IF;
            probe := probe + 1;
    END;

    -- **A permission, which no refusal probe can see**: a touchpoint written up three days
    -- after the conversation is the ordinary case -- "a salesperson writes up Friday's open
    -- day on Monday" -- so the forward-only bound must admit it.
    BEGIN
        INSERT INTO plt01.crm_touchpoints
            (tenant_id, lead_id, kind, occurred_at, summary, recorded_by, correlation_id)
        VALUES ('11111111-1111-4111-8111-111111111111',
                'cccccccc-9000-4000-8000-000000000002', 'tour',
                now() - interval '3 days', 'met her at the open day',
                '33333333-3333-4333-8333-333333333333',
                '33333333-3333-4333-8333-333333333333');
        probe := probe + 1;
    EXCEPTION
        WHEN others THEN
            RAISE EXCEPTION
                'CHECK 115 FAILED: a touchpoint written up three days late was refused, and '
                'a salesperson writes up Friday''s open day on Monday';
    END;


    -- ---- ADR-0010 D8 to D11: the loss, its reason, and the interest withdrawal ----------
    --
    -- One case per rule and per *side* of each biconditional. The attribution constraint has
    -- three ways to be wrong -- lost with no reason, a reason while live, and a loss nobody
    -- recorded -- and only one of them is the case a reader would think of first.
    -- A lead marked lost with nothing to show for it.
    BEGIN
        UPDATE plt01.crm_leads SET lost_at = now()
         WHERE lead_id = 'cccccccc-9000-4000-8000-000000000002';
        RAISE EXCEPTION 'CHECK 115 FAILED: a lead lost for no stated reason';
    EXCEPTION
        WHEN check_violation THEN
            GET STACKED DIAGNOSTICS offender = CONSTRAINT_NAME;
            IF offender <> 'crm_leads_lost_is_reasoned_and_attributed' THEN
                RAISE EXCEPTION 'CHECK 115 FAILED: refused by % instead', offender;
            END IF;
            probe := probe + 1;
    END;

    -- The other side: a reason on a lead nobody has lost, which the report would count.
    BEGIN
        UPDATE plt01.crm_leads
           SET lost_reason = 'too_expensive', lost_by = '33333333-3333-4333-8333-333333333333'
         WHERE lead_id = 'cccccccc-9000-4000-8000-000000000002';
        RAISE EXCEPTION 'CHECK 115 FAILED: a live lead carrying a lost reason';
    EXCEPTION
        WHEN check_violation THEN
            GET STACKED DIAGNOSTICS offender = CONSTRAINT_NAME;
            IF offender <> 'crm_leads_lost_is_reasoned_and_attributed' THEN
                RAISE EXCEPTION 'CHECK 115 FAILED: refused by % instead', offender;
            END IF;
            probe := probe + 1;
    END;

    -- And a loss with a reason and nobody's name on it.
    BEGIN
        UPDATE plt01.crm_leads
           SET lost_at = now(), lost_reason = 'too_expensive'
         WHERE lead_id = 'cccccccc-9000-4000-8000-000000000002';
        RAISE EXCEPTION 'CHECK 115 FAILED: a loss nobody recorded';
    EXCEPTION
        WHEN check_violation THEN
            GET STACKED DIAGNOSTICS offender = CONSTRAINT_NAME;
            IF offender <> 'crm_leads_lost_is_reasoned_and_attributed' THEN
                RAISE EXCEPTION 'CHECK 115 FAILED: refused by % instead', offender;
            END IF;
            probe := probe + 1;
    END;

    -- **And a loss with a name and no reason**, which is the third way the attribution
    -- constraint can be wrong and the one no other case here sends. The sweep found it: with
    -- the reason conjunct weakened away, every case above was still refused by the actor half.
    BEGIN
        UPDATE plt01.crm_leads
           SET lost_at = now(), lost_by = '33333333-3333-4333-8333-333333333333'
         WHERE lead_id = 'cccccccc-9000-4000-8000-000000000002';
        RAISE EXCEPTION 'CHECK 115 FAILED: a loss with a name and no reason';
    EXCEPTION
        WHEN check_violation THEN
            GET STACKED DIAGNOSTICS offender = CONSTRAINT_NAME;
            IF offender <> 'crm_leads_lost_is_reasoned_and_attributed' THEN
                RAISE EXCEPTION 'CHECK 115 FAILED: refused by % instead', offender;
            END IF;
            probe := probe + 1;
    END;

    -- A reason outside the four ADM-CRM-07 draws. Closed because ADM-RPT-03 groups by it.
    BEGIN
        UPDATE plt01.crm_leads
           SET lost_at = now(), lost_reason = 'changed_their_mind',
               lost_by = '33333333-3333-4333-8333-333333333333'
         WHERE lead_id = 'cccccccc-9000-4000-8000-000000000002';
        RAISE EXCEPTION 'CHECK 115 FAILED: a lost reason outside the four';
    EXCEPTION
        WHEN check_violation THEN
            GET STACKED DIAGNOSTICS offender = CONSTRAINT_NAME;
            IF offender <> 'crm_leads_lost_reason' THEN
                RAISE EXCEPTION 'CHECK 115 FAILED: refused by % instead', offender;
            END IF;
            probe := probe + 1;
    END;

    -- A detail about a loss that did not happen.
    BEGIN
        UPDATE plt01.crm_leads SET lost_detail = 'he joined the one on Mecca Street'
         WHERE lead_id = 'cccccccc-9000-4000-8000-000000000002';
        RAISE EXCEPTION 'CHECK 115 FAILED: a detail about a loss that did not happen';
    EXCEPTION
        WHEN check_violation THEN
            GET STACKED DIAGNOSTICS offender = CONSTRAINT_NAME;
            IF offender <> 'crm_leads_lost_detail_needs_a_loss' THEN
                RAISE EXCEPTION 'CHECK 115 FAILED: refused by % instead', offender;
            END IF;
            probe := probe + 1;
    END;

    -- A detail of whitespace is a field nobody filled in. A tab, not spaces: `btrim` strips
    -- spaces and nothing else, which is why this repository standardised on the regex form.
    BEGIN
        UPDATE plt01.crm_leads
           SET lost_at = now(), lost_reason = 'joined_elsewhere',
               lost_by = '33333333-3333-4333-8333-333333333333', lost_detail = E'\t'
         WHERE lead_id = 'cccccccc-9000-4000-8000-000000000002';
        RAISE EXCEPTION 'CHECK 115 FAILED: a lost detail of whitespace';
    EXCEPTION
        WHEN check_violation THEN
            GET STACKED DIAGNOSTICS offender = CONSTRAINT_NAME;
            IF offender <> 'crm_leads_lost_detail_said_something' THEN
                RAISE EXCEPTION 'CHECK 115 FAILED: refused by % instead', offender;
            END IF;
            probe := probe + 1;
    END;

    -- The other conjunct: past its bound, which otherwise reaches a column limit as a
    -- `DataError` rather than the `CheckViolation` the handlers catch.
    BEGIN
        UPDATE plt01.crm_leads
           SET lost_at = now(), lost_reason = 'joined_elsewhere',
               lost_by = '33333333-3333-4333-8333-333333333333', lost_detail = repeat('x', 501)
         WHERE lead_id = 'cccccccc-9000-4000-8000-000000000002';
        RAISE EXCEPTION 'CHECK 115 FAILED: a lost detail past its bound';
    EXCEPTION
        WHEN check_violation THEN
            GET STACKED DIAGNOSTICS offender = CONSTRAINT_NAME;
            IF offender <> 'crm_leads_lost_detail_said_something' THEN
                RAISE EXCEPTION 'CHECK 115 FAILED: refused by % instead', offender;
            END IF;
            probe := probe + 1;
    END;

    -- **And the permission, which no refusal case can see.** A constraint set that refused the
    -- ordinary loss would make the whole feature unusable while every case above still passed.
    BEGIN
        UPDATE plt01.crm_leads
           SET lost_at = now(), lost_reason = 'joined_elsewhere', lost_by = '33333333-3333-4333-8333-333333333333',
               lost_detail = 'he joined the one on Mecca Street'
         WHERE lead_id = 'cccccccc-9000-4000-8000-000000000002';
        UPDATE plt01.crm_leads
           SET lost_at = NULL, lost_reason = NULL, lost_by = NULL, lost_detail = NULL
         WHERE lead_id = 'cccccccc-9000-4000-8000-000000000002';
        probe := probe + 1;
    EXCEPTION
        WHEN others THEN
            GET STACKED DIAGNOSTICS offender = CONSTRAINT_NAME, state = RETURNED_SQLSTATE;
            RAISE EXCEPTION
                'CHECK 115 FAILED: the ordinary loss and its reopening were refused by % (%)',
                coalesce(nullif(offender, ''), 'nothing named'), state;
    END;

    -- ---- the interest withdrawal, which needs rows of its own -------------------------
    --
    -- **The seed has no interests**, so these cases insert what they exercise. The first
    -- version of them did not, and an `UPDATE ... WHERE lead_id = ...` that matches zero rows
    -- succeeds -- so the case reported a missing constraint that was there all along. A case
    -- whose row does not exist proves nothing.
    --
    -- They share one transaction, so each uses its own interest: `classes` stays live for the
    -- duplicate case and `pt` is withdrawn for the one-way and re-record cases.
    INSERT INTO plt01.crm_lead_interests
        (tenant_id, lead_id, interest, recorded_by, correlation_id)
    VALUES ('11111111-1111-4111-8111-111111111111', 'cccccccc-9000-4000-8000-000000000002', 'classes', '33333333-3333-4333-8333-333333333333', '33333333-3333-4333-8333-333333333333'),
           ('11111111-1111-4111-8111-111111111111', 'cccccccc-9000-4000-8000-000000000002', 'pt', '33333333-3333-4333-8333-333333333333', '33333333-3333-4333-8333-333333333333');

    -- A withdrawal with nobody's name on it. Taking an interest back is a decision somebody
    -- made, and "evidence with nobody's name on it answers nothing".
    BEGIN
        UPDATE plt01.crm_lead_interests SET withdrawn_at = now()
         WHERE lead_id = 'cccccccc-9000-4000-8000-000000000002' AND interest = 'classes';
        RAISE EXCEPTION 'CHECK 115 FAILED: a withdrawal nobody recorded';
    EXCEPTION
        WHEN check_violation THEN
            GET STACKED DIAGNOSTICS offender = CONSTRAINT_NAME;
            IF offender <> 'crm_lead_interests_withdrawal_is_attributed' THEN
                RAISE EXCEPTION 'CHECK 115 FAILED: refused by % instead', offender;
            END IF;
            probe := probe + 1;
    END;

    -- Two live rows for one interest is still refused, which is `0027`'s rule surviving the
    -- index becoming partial.
    BEGIN
        INSERT INTO plt01.crm_lead_interests
            (tenant_id, lead_id, interest, recorded_by, correlation_id)
        VALUES ('11111111-1111-4111-8111-111111111111', 'cccccccc-9000-4000-8000-000000000002', 'classes', '33333333-3333-4333-8333-333333333333', '33333333-3333-4333-8333-333333333333');
        RAISE EXCEPTION 'CHECK 115 FAILED: one interest recorded live twice';
    EXCEPTION
        WHEN unique_violation THEN
            GET STACKED DIAGNOSTICS offender = CONSTRAINT_NAME;
            IF offender <> 'crm_lead_interests_one_live' THEN
                RAISE EXCEPTION 'CHECK 115 FAILED: refused by % instead', offender;
            END IF;
            probe := probe + 1;
    END;

    -- **One way, because a CHECK cannot see what a row used to be.** Clearing a withdrawal
    -- makes the interest read as never withdrawn; re-dating it makes when somebody changed
    -- their mind unanswerable. Both are the same trigger and the second is the one a
    -- `withdrawn_at IS NULL` probe would miss entirely.
    UPDATE plt01.crm_lead_interests
       SET withdrawn_at = now(), withdrawn_by = '33333333-3333-4333-8333-333333333333'
     WHERE lead_id = 'cccccccc-9000-4000-8000-000000000002' AND interest = 'pt';
    BEGIN
        UPDATE plt01.crm_lead_interests SET withdrawn_at = NULL, withdrawn_by = NULL
         WHERE lead_id = 'cccccccc-9000-4000-8000-000000000002' AND interest = 'pt';
        RAISE EXCEPTION 'CHECK 115 FAILED: a withdrawal that was cleared';
    EXCEPTION
        -- **The handler has to tell the trigger's refusal from this case's own failure.**
        -- Both are `raise_exception`, so `WHEN raise_exception THEN probe := probe + 1`
        -- counted the failure as a pass -- and the sweep found it by dropping the trigger and
        -- watching the suite stay green. Any `CHECK 115 FAILED` is re-raised.
        WHEN raise_exception THEN
            GET STACKED DIAGNOSTICS wrong = MESSAGE_TEXT;
            IF wrong LIKE 'CHECK 115 FAILED%' THEN
                RAISE EXCEPTION '%', wrong;
            END IF;
            probe := probe + 1;
    END;

    BEGIN
        UPDATE plt01.crm_lead_interests SET withdrawn_at = now() - interval '30 days'
         WHERE lead_id = 'cccccccc-9000-4000-8000-000000000002' AND interest = 'pt';
        RAISE EXCEPTION 'CHECK 115 FAILED: a withdrawal that was re-dated';
    EXCEPTION
        WHEN raise_exception THEN
            GET STACKED DIAGNOSTICS wrong = MESSAGE_TEXT;
            IF wrong LIKE 'CHECK 115 FAILED%' THEN
                RAISE EXCEPTION '%', wrong;
            END IF;
            probe := probe + 1;
    END;

    -- **The partial index, from the side that has to be admitted.** `0027`'s key was one row
    -- per (tenant, lead, interest), which is right while the set only grows and wrong the
    -- moment one can be withdrawn: a lead who wanted PT, changed their mind and changed it
    -- back would be refused by the row they withdrew. Only a case that must *succeed* sees it.
    BEGIN
        INSERT INTO plt01.crm_lead_interests
            (tenant_id, lead_id, interest, recorded_by, correlation_id)
        VALUES ('11111111-1111-4111-8111-111111111111', 'cccccccc-9000-4000-8000-000000000002', 'pt', '33333333-3333-4333-8333-333333333333', '33333333-3333-4333-8333-333333333333');
        probe := probe + 1;
    EXCEPTION
        WHEN others THEN
            GET STACKED DIAGNOSTICS offender = CONSTRAINT_NAME, state = RETURNED_SQLSTATE;
            RAISE EXCEPTION
                'CHECK 115 FAILED: an interest asked for again after a withdrawal was '
                'refused by % (%)',
                coalesce(nullif(offender, ''), 'nothing named'), state;
    END;
    IF probe <> 32 THEN
        RAISE EXCEPTION
            'CHECK 115 FAILED: % cases ran, expected 32 -- a case that stops running is a '
            'rule with no evidence behind it', probe;
    END IF;
END $$;
ROLLBACK;

-- ========================================================= CHECK 116 (MOD-008)
--
-- **ADM-STF-03's invitation, one case per rule.** ADR-0017. `0007` adds the first table in
-- `iam` a route can reach a CHECK through, so these are its only behavioural evidence: the
-- module's own checks 30-32 pin policies and privileges and no constraint set, which is the
-- `iam`-plane gap `CLAUDE.md` records.
--
-- Every case names the constraint that refused it and records a different one as a
-- *confusion*, so a sibling answering fails on a clean database rather than at the next
-- sweep -- the trap this repository has shipped in five modules.
--
-- **Two permissions first**, because no number of refusals can see a rule tightened until an
-- ordinary invitation is unwritable: the canvas's own row, and the accept that settles it.
BEGIN;
SET LOCAL ROLE veyro_iam_app;
SET LOCAL app.tenant_id = '11111111-1111-4111-8111-111111111111';
DO $$
DECLARE
    probe integer := 0;
    offender text;
    state text;
    confused text[] := ARRAY[]::text[];
    tenant constant uuid := '11111111-1111-4111-8111-111111111111';
    inviter constant uuid := 'eeeeeeee-0000-4000-8000-000000000002';
    joiner constant uuid := 'eeeeeeee-0000-4000-8000-00000000000a';
    sales constant uuid := 'ffffffff-0000-4000-8000-000000000001';
    live constant uuid := 'aaaaaaaa-0007-4000-8000-000000000001';
    spare constant uuid := 'aaaaaaaa-0007-4000-8000-000000000002';
    digest_a constant bytea := decode(md5('a') || md5('b'), 'hex');
    digest_b constant bytea := decode(md5('c') || md5('d'), 'hex');
    digest_c constant bytea := decode(md5('e') || md5('f'), 'hex');
BEGIN
    -- 1. The permission: the canvas's own invitation, seven days out.
    BEGIN
        INSERT INTO iam.invitations
            (tenant_id, invitation_id, email_normalized, role_id, token_hash, expires_at,
             created_by, correlation_id)
        VALUES (tenant, live, 'kareem@nadi.jo', sales, digest_a, now() + interval '7 days',
                inviter, inviter);
        INSERT INTO iam.invitation_scopes
            (tenant_id, invitation_id, scope_type)
        VALUES (tenant, live, 'tenant');
        probe := probe + 1;
    EXCEPTION
        WHEN others THEN
            GET STACKED DIAGNOSTICS offender = CONSTRAINT_NAME, state = RETURNED_SQLSTATE;
            confused := array_append(
                confused, 'an ordinary invitation was refused by '
                || coalesce(nullif(offender, ''), 'nothing named') || ' sqlstate ' || state);
    END;

    -- 2. And the accept, which is the one update the grant admits.
    BEGIN
        UPDATE iam.invitations
        SET accepted_at = now(), accepted_identity_id = joiner
        WHERE invitation_id = live;
        probe := probe + 1;
    EXCEPTION
        WHEN others THEN
            GET STACKED DIAGNOSTICS offender = CONSTRAINT_NAME, state = RETURNED_SQLSTATE;
            confused := array_append(
                confused, 'an ordinary accept was refused by '
                || coalesce(nullif(offender, ''), 'nothing named') || ' sqlstate ' || state);
    END;

    -- 3. Accepted once, and by whom is recorded once. A CHECK cannot see `OLD`.
    BEGIN
        UPDATE iam.invitations
        SET accepted_identity_id = inviter WHERE invitation_id = live;
        RAISE EXCEPTION 'CHECK 116 FAILED: an acceptance was re-attributed';
    EXCEPTION
        WHEN raise_exception THEN
            IF SQLERRM LIKE 'CHECK 116 FAILED%' THEN RAISE; END IF;
            probe := probe + 1;
        WHEN others THEN
            GET STACKED DIAGNOSTICS offender = CONSTRAINT_NAME, state = RETURNED_SQLSTATE;
            confused := array_append(
                confused, 'the re-attributed acceptance answered by '
                || coalesce(nullif(offender, ''), 'nothing named') || ' sqlstate ' || state);
    END;

    -- 4. And not both outcomes: a row saying accepted *and* withdrawn is one nobody can read.
    BEGIN
        UPDATE iam.invitations
        SET revoked_at = now(), revoked_by = inviter, revoke_reason = 'changed our mind'
        WHERE invitation_id = live;
        RAISE EXCEPTION 'CHECK 116 FAILED: an accepted invitation was also withdrawn';
    EXCEPTION
        WHEN check_violation THEN
            GET STACKED DIAGNOSTICS offender = CONSTRAINT_NAME;
            IF offender = 'invitations_one_outcome' THEN probe := probe + 1;
            ELSE confused := array_append(
                confused, 'the double outcome answered by ' || offender); END IF;
        WHEN raise_exception THEN
            IF SQLERRM LIKE 'CHECK 116 FAILED%' THEN RAISE; END IF;
            confused := array_append(confused, 'the double outcome raised ' || SQLERRM);
    END;

    -- 5. A second live invitation to the same address, which is the whole of D5: whichever
    -- link they click would decide what they can do.
    BEGIN
        INSERT INTO iam.invitations
            (tenant_id, invitation_id, email_normalized, role_id, token_hash, expires_at,
             created_by, correlation_id)
        VALUES (tenant, spare, 'yasmin@nadi.jo', sales, digest_b, now() + interval '7 days',
                inviter, inviter);
        INSERT INTO iam.invitations
            (tenant_id, email_normalized, role_id, token_hash, expires_at, created_by,
             correlation_id)
        VALUES (tenant, 'yasmin@nadi.jo', sales, digest_c, now() + interval '7 days',
                inviter, inviter);
        RAISE EXCEPTION 'CHECK 116 FAILED: two live invitations to one address';
    EXCEPTION
        WHEN unique_violation THEN
            GET STACKED DIAGNOSTICS offender = CONSTRAINT_NAME;
            IF offender = 'invitations_one_live_per_email' THEN probe := probe + 1;
            ELSE confused := array_append(
                confused, 'the repeated address answered by ' || offender); END IF;
        WHEN raise_exception THEN
            IF SQLERRM LIKE 'CHECK 116 FAILED%' THEN RAISE; END IF;
            confused := array_append(confused, 'the repeated address raised ' || SQLERRM);
    END;

    -- 6. And a withdrawn one frees the slot, which only a case the index must *admit* can
    -- see: the resend revokes and inserts in one transaction (D4), so a drop-only case would
    -- pass with the whole partial clause removed.
    -- **Its own row, because case 5 rolled back and took the one it inserted with it.** A
    -- probe that depends on a sibling's committed state depends on that sibling passing --
    -- the trap this repository records for MOD-017's own entitlement block, hit again here.
    BEGIN
        INSERT INTO iam.invitations
            (tenant_id, invitation_id, email_normalized, role_id, token_hash, expires_at,
             created_by, correlation_id)
        VALUES (tenant, spare, 'yasmin@nadi.jo', sales, digest_b, now() + interval '7 days',
                inviter, inviter);
        UPDATE iam.invitations
        SET revoked_at = now(), revoked_by = inviter,
            revoke_reason = 'resent: a new link was issued'
        WHERE invitation_id = spare;
        INSERT INTO iam.invitations
            (tenant_id, email_normalized, role_id, token_hash, expires_at,
             supersedes_invitation_id, created_by, correlation_id)
        VALUES (tenant, 'yasmin@nadi.jo', sales, digest_c, now() + interval '7 days', spare,
                inviter, inviter);
        probe := probe + 1;
    EXCEPTION
        WHEN others THEN
            GET STACKED DIAGNOSTICS offender = CONSTRAINT_NAME, state = RETURNED_SQLSTATE;
            confused := array_append(
                confused, 'a resend after a withdrawal was refused by '
                || coalesce(nullif(offender, ''), 'nothing named') || ' sqlstate ' || state);
    END;

    -- 7. A withdrawal with no stated reason. **The NULL case, not a blank one**: the
    -- `coalesce` is what this proves, and every blank-reason case in this build passed with
    -- it gone until MOD-014's sweep found that.
    BEGIN
        INSERT INTO iam.invitations
            (tenant_id, email_normalized, role_id, token_hash, expires_at, revoked_at,
             revoked_by, created_by, correlation_id)
        VALUES (tenant, 'omar.s@nadi.jo', sales, decode(md5('g') || md5('h'), 'hex'),
                now() + interval '7 days', now(), inviter, inviter, inviter);
        RAISE EXCEPTION 'CHECK 116 FAILED: a withdrawal stating no reason at all';
    EXCEPTION
        WHEN check_violation THEN
            GET STACKED DIAGNOSTICS offender = CONSTRAINT_NAME;
            IF offender = 'invitations_revocation_attributed' THEN probe := probe + 1;
            ELSE confused := array_append(
                confused, 'the unreasoned withdrawal answered by ' || offender); END IF;
    END;

    -- 8. And one of a single tab, which proves the `~ '[^[:space:]]'` form rather than the
    -- `length(btrim(...))` one this repository banned across 122 constraints.
    BEGIN
        INSERT INTO iam.invitations
            (tenant_id, email_normalized, role_id, token_hash, expires_at, revoked_at,
             revoked_by, revoke_reason, created_by, correlation_id)
        VALUES (tenant, 'omar.s@nadi.jo', sales, decode(md5('i') || md5('j'), 'hex'),
                now() + interval '7 days', now(), inviter, E'\t', inviter, inviter);
        RAISE EXCEPTION 'CHECK 116 FAILED: a withdrawal reason of one tab';
    EXCEPTION
        WHEN check_violation THEN
            GET STACKED DIAGNOSTICS offender = CONSTRAINT_NAME;
            IF offender = 'invitations_revocation_attributed' THEN probe := probe + 1;
            ELSE confused := array_append(
                confused, 'the whitespace reason answered by ' || offender); END IF;
    END;

    -- 9. A window past the ceiling (D8): a year-long invitation is a permanent back door
    -- with a friendly name.
    BEGIN
        INSERT INTO iam.invitations
            (tenant_id, email_normalized, role_id, token_hash, expires_at, created_by,
             correlation_id)
        VALUES (tenant, 'late@nadi.jo', sales, decode(md5('k') || md5('l'), 'hex'),
                now() + interval '31 days', inviter, inviter);
        RAISE EXCEPTION 'CHECK 116 FAILED: an invitation lasting a month and a day';
    EXCEPTION
        WHEN check_violation THEN
            GET STACKED DIAGNOSTICS offender = CONSTRAINT_NAME;
            IF offender = 'invitations_window' THEN probe := probe + 1;
            ELSE confused := array_append(
                confused, 'the long window answered by ' || offender); END IF;
    END;

    -- 10. And one that has already closed, which is the other side of the same rule.
    BEGIN
        INSERT INTO iam.invitations
            (tenant_id, email_normalized, role_id, token_hash, expires_at, created_by,
             correlation_id)
        VALUES (tenant, 'past@nadi.jo', sales, decode(md5('m') || md5('n'), 'hex'),
                now() - interval '1 day', inviter, inviter);
        RAISE EXCEPTION 'CHECK 116 FAILED: an invitation that expired before it existed';
    EXCEPTION
        WHEN check_violation THEN
            GET STACKED DIAGNOSTICS offender = CONSTRAINT_NAME;
            IF offender = 'invitations_window' THEN probe := probe + 1;
            ELSE confused := array_append(
                confused, 'the closed window answered by ' || offender); END IF;
    END;

    -- 11. A token that is not a 32-byte digest, which is what makes "only the digest is
    -- here" a control rather than a naming convention -- MOD-012's `vault_ref` lesson.
    BEGIN
        INSERT INTO iam.invitations
            (tenant_id, email_normalized, role_id, token_hash, expires_at, created_by,
             correlation_id)
        VALUES (tenant, 'short@nadi.jo', sales, decode('abcd', 'hex'),
                now() + interval '7 days', inviter, inviter);
        RAISE EXCEPTION 'CHECK 116 FAILED: a token hash that is not a digest';
    EXCEPTION
        WHEN check_violation THEN
            GET STACKED DIAGNOSTICS offender = CONSTRAINT_NAME;
            IF offender = 'invitations_token_hash_length' THEN probe := probe + 1;
            ELSE confused := array_append(
                confused, 'the short digest answered by ' || offender); END IF;
    END;

    -- 12. An address that is not one, so the one-live index means "this person".
    BEGIN
        INSERT INTO iam.invitations
            (tenant_id, email_normalized, role_id, token_hash, expires_at, created_by,
             correlation_id)
        VALUES (tenant, 'not an address', sales, decode(md5('o') || md5('p'), 'hex'),
                now() + interval '7 days', inviter, inviter);
        RAISE EXCEPTION 'CHECK 116 FAILED: an invitation to something that is not an address';
    EXCEPTION
        WHEN check_violation THEN
            GET STACKED DIAGNOSTICS offender = CONSTRAINT_NAME;
            IF offender = 'invitations_email_shape' THEN probe := probe + 1;
            ELSE confused := array_append(
                confused, 'the bad address answered by ' || offender); END IF;
    END;

    -- 13. A club shape `role_assignments` would refuse, because these rows become those rows.
    BEGIN
        INSERT INTO iam.invitation_scopes
            (tenant_id, invitation_id, scope_type, location_id)
        VALUES (tenant, live, 'tenant', 'cccccccc-0000-4000-8000-000000000001');
        RAISE EXCEPTION 'CHECK 116 FAILED: a tenant-wide scope naming a club';
    EXCEPTION
        WHEN check_violation THEN
            GET STACKED DIAGNOSTICS offender = CONSTRAINT_NAME;
            IF offender = 'invitation_scopes_shape' THEN probe := probe + 1;
            ELSE confused := array_append(
                confused, 'the bad scope answered by ' || offender); END IF;
        WHEN foreign_key_violation THEN
            RAISE EXCEPTION
                'CHECK 116 FAILED: a tenant-wide scope naming a club was refused by the '
                'foreign key, not the shape rule';
    END;

    -- 14. And the same club twice on one invitation, which the accept would turn into two
    -- assignments the second of which `role_assignments` refuses.
    BEGIN
        INSERT INTO iam.invitation_scopes (tenant_id, invitation_id, scope_type)
        VALUES (tenant, live, 'tenant');
        RAISE EXCEPTION 'CHECK 116 FAILED: one club named twice on one invitation';
    EXCEPTION
        WHEN unique_violation THEN
            GET STACKED DIAGNOSTICS offender = CONSTRAINT_NAME;
            IF offender = 'invitation_scopes_one_per_scope' THEN probe := probe + 1;
            ELSE confused := array_append(
                confused, 'the repeated club answered by ' || offender); END IF;
    END;

    -- 15 to 16. The trigger's fourth branch: the link, the role and the window are what the
    -- invitation *is*, and a resend is a new row rather than a rewritten one (D4). The grant
    -- refuses these columns too, so the trigger's own refusal is probed as the owner in 116b
    -- -- here it is the *grant* that answers, which is the stronger control. **The address is
    -- deliberately not among them**: `0007` grants it so MOD-009's erasure can clear it on a
    -- settled row, and what holds it still while the link is alive is the trigger alone,
    -- which is 116b's third and sixth probes.
    BEGIN
        UPDATE iam.invitations SET expires_at = now() + interval '20 days'
        WHERE invitation_id = live;
        RAISE EXCEPTION 'CHECK 116 FAILED: an expiry was moved by the service role';
    EXCEPTION
        WHEN insufficient_privilege THEN probe := probe + 1;
        WHEN raise_exception THEN
            IF SQLERRM LIKE 'CHECK 116 FAILED%' THEN RAISE; END IF;
            confused := array_append(
                confused, 'the moved expiry was refused by the trigger rather than the grant');
    END;
    BEGIN
        UPDATE iam.invitations SET token_hash = digest_b WHERE invitation_id = live;
        RAISE EXCEPTION 'CHECK 116 FAILED: a token was replaced by the service role';
    EXCEPTION
        WHEN insufficient_privilege THEN probe := probe + 1;
        WHEN raise_exception THEN
            IF SQLERRM LIKE 'CHECK 116 FAILED%' THEN RAISE; END IF;
            confused := array_append(
                confused, 'the replaced token was refused by the trigger rather than the '
                'grant');
    END;

    IF array_length(confused, 1) IS NOT NULL THEN
        RAISE EXCEPTION 'CHECK 116 FAILED: %', array_to_string(confused, '; ');
    END IF;
    IF probe <> 16 THEN
        RAISE EXCEPTION
            'CHECK 116 FAILED: % of 16 cases ran -- a rule with no isolating case is a rule '
            'nobody has tested', probe;
    END IF;
END $$;
ROLLBACK;

-- ---------------------------------- 116b. the trigger, for the writer the grant is not
-- **The five branches, as the table owner.** Three of the columns the trigger freezes carry no
-- UPDATE grant at all, so under `veyro_iam_app` the privilege layer answers first -- which
-- check 116 proves and which says nothing about the trigger. This is MOD-020's own arrangement
-- in 97c and MOD-026's in 114, and for the same reason: the grant is the stronger control and
-- the trigger is what holds for a writer that is not this service.
--
-- **And one of the five is a permission**, which is the only thing that can see the address
-- branch tightened until an erasure cannot reach a settled row. The address is the one column
-- here where the trigger is not a second line of defence but the whole of it.
BEGIN;
SET LOCAL app.tenant_id = '11111111-1111-4111-8111-111111111111';
DO $$
DECLARE
    probe integer := 0;
    tenant constant uuid := '11111111-1111-4111-8111-111111111111';
    inviter constant uuid := 'eeeeeeee-0000-4000-8000-000000000002';
    joiner constant uuid := 'eeeeeeee-0000-4000-8000-00000000000a';
    sales constant uuid := 'ffffffff-0000-4000-8000-000000000001';
    one constant uuid := 'aaaaaaaa-0007-4000-8000-00000000000a';
    state text;
BEGIN
    INSERT INTO iam.invitations
        (tenant_id, invitation_id, email_normalized, role_id, token_hash, expires_at,
         created_by, correlation_id)
    VALUES (tenant, one, 'owner@nadi.jo', sales, decode(md5('q') || md5('r'), 'hex'),
            now() + interval '7 days', inviter, inviter);

    -- 1. The link.
    BEGIN
        UPDATE iam.invitations SET token_hash = decode(md5('s') || md5('t'), 'hex')
        WHERE invitation_id = one;
        RAISE EXCEPTION 'CHECK 116 FAILED: the owner replaced an invitation''s link';
    EXCEPTION
        WHEN raise_exception THEN
            IF SQLERRM LIKE 'CHECK 116 FAILED%' THEN RAISE; END IF;
            probe := probe + 1;
    END;
    -- 2. The window.
    BEGIN
        UPDATE iam.invitations SET expires_at = now() + interval '20 days'
        WHERE invitation_id = one;
        RAISE EXCEPTION 'CHECK 116 FAILED: the owner moved an invitation''s window';
    EXCEPTION
        WHEN raise_exception THEN
            IF SQLERRM LIKE 'CHECK 116 FAILED%' THEN RAISE; END IF;
            probe := probe + 1;
    END;
    -- 3. The address, while the link is alive. This is the branch that keeps a bearer
    -- credential from being redirected, and it is the whole control rather than half of one:
    -- the column carries an UPDATE grant so that an erasure can reach a settled row.
    BEGIN
        UPDATE iam.invitations SET email_normalized = 'somebody.else@nadi.jo'
        WHERE invitation_id = one;
        RAISE EXCEPTION 'CHECK 116 FAILED: the owner re-pointed a live invitation''s address';
    EXCEPTION
        WHEN raise_exception THEN
            IF SQLERRM LIKE 'CHECK 116 FAILED%' THEN RAISE; END IF;
            probe := probe + 1;
    END;
    -- 4. Accepted once, and by whom recorded once.
    BEGIN
        UPDATE iam.invitations
        SET accepted_at = now(), accepted_identity_id = joiner WHERE invitation_id = one;
        UPDATE iam.invitations SET accepted_at = now() + interval '1 hour'
        WHERE invitation_id = one;
        RAISE EXCEPTION 'CHECK 116 FAILED: the owner re-dated an acceptance';
    EXCEPTION
        WHEN raise_exception THEN
            IF SQLERRM LIKE 'CHECK 116 FAILED%' THEN RAISE; END IF;
            probe := probe + 1;
    END;
    -- 5. And the withdrawal branch, which nothing above reaches. **Its own row**, because
    -- probe 4 rolled back and took its acceptance with it -- the same
    -- depends-on-a-sibling's-committed-state trap, one block in.
    BEGIN
        INSERT INTO iam.invitations
            (tenant_id, invitation_id, email_normalized, role_id, token_hash, expires_at,
             created_by, correlation_id)
        VALUES (tenant, 'aaaaaaaa-0007-4000-8000-00000000000b', 'gone@nadi.jo', sales,
                decode(md5('u') || md5('v'), 'hex'), now() + interval '7 days', inviter,
                inviter);
        UPDATE iam.invitations
        SET revoked_at = now(), revoked_by = inviter, revoke_reason = 'took another job'
        WHERE invitation_id = 'aaaaaaaa-0007-4000-8000-00000000000b';
        UPDATE iam.invitations SET revoke_reason = 'something else'
        WHERE invitation_id = 'aaaaaaaa-0007-4000-8000-00000000000b';
        RAISE EXCEPTION 'CHECK 116 FAILED: the owner rewrote why an invitation was withdrawn';
    EXCEPTION
        WHEN raise_exception THEN
            IF SQLERRM LIKE 'CHECK 116 FAILED%' THEN RAISE; END IF;
            probe := probe + 1;
    END;

    -- 6. **The permission**, and it is the one case the five refusals cannot produce: a
    -- settled invitation's address *may* move, because that is how MOD-009's erasure clears
    -- the copy of a staff member's email this row holds in the clear. Tighten the branch
    -- above to "the address never moves" and every refusal probe still passes while the
    -- erasure the registry promises fails at run time. Its own row again, for probe 5's
    -- reason.
    BEGIN
        INSERT INTO iam.invitations
            (tenant_id, invitation_id, email_normalized, role_id, token_hash, expires_at,
             created_by, correlation_id, accepted_at, accepted_identity_id)
        VALUES (tenant, 'aaaaaaaa-0007-4000-8000-00000000000c', 'joined@nadi.jo', sales,
                decode(md5('w') || md5('x'), 'hex'), now() + interval '7 days', inviter,
                inviter, now(), joiner);
        UPDATE iam.invitations
        SET email_normalized = 'erased-' || invitation_id::text || '@erased.invalid'
        WHERE invitation_id = 'aaaaaaaa-0007-4000-8000-00000000000c';
        probe := probe + 1;
    EXCEPTION
        WHEN others THEN
            GET STACKED DIAGNOSTICS state = RETURNED_SQLSTATE;
            RAISE EXCEPTION
                'CHECK 116 FAILED: an accepted invitation''s address could not be erased (%): '
                '%', state, SQLERRM;
    END;

    -- The trigger function's own properties, which `md5(prosrc)` cannot see.
    IF (SELECT count(*) FROM pg_proc p
         WHERE p.pronamespace = 'iam'::regnamespace
           AND p.proname = 'invitation_is_settled_once'
           AND 'search_path=pg_catalog, public' = ANY (coalesce(p.proconfig, '{}'))) <> 1 THEN
        RAISE EXCEPTION 'CHECK 116 FAILED: the trigger function has no pinned search_path';
    END IF;
    IF (SELECT bool_or(p.prosecdef OR has_function_privilege('public', p.oid, 'EXECUTE'))
          FROM pg_proc p
         WHERE p.pronamespace = 'iam'::regnamespace
           AND p.proname = 'invitation_is_settled_once') THEN
        RAISE EXCEPTION
            'CHECK 116 FAILED: the trigger function is SECURITY DEFINER or PUBLIC-executable';
    END IF;
    IF (SELECT tgenabled FROM pg_trigger
         WHERE tgrelid = 'iam.invitations'::regclass
           AND tgname = 'invitations_settled_once') <> 'O' THEN
        RAISE EXCEPTION 'CHECK 116 FAILED: the trigger is disabled';
    END IF;

    IF probe <> 6 THEN
        RAISE EXCEPTION
            'CHECK 116 FAILED: the settled-once trigger answered % of 6 cases', probe;
    END IF;
END $$;
ROLLBACK;

-- ---------------------------------- 116c. the columns and the grants, compared as sets
-- **Two absences and one widening, and none of the three has any other evidence.** MOD-012's
-- rule, because in both places the control is an *absence* and an absence is exactly what a
-- later migration adds back:
--
--   * there is **no column a token could live in**. `token_hash` is the digest and the
--     plaintext exists once, in the response that minted it, which is `iam.sessions`' shape --
--     so a `token`, `link` or `url` column here would make the whole of D3 a convention.
--   * there is **no name**. The canvas collects an address, a role and the clubs, and a
--     `display_name` was in the first draft of this table until the canvas was read against
--     it -- a copy of somebody's name in the plane whose own authentication log deliberately
--     records none. Nothing else in this suite would notice it coming back.
--   * and the **column-scoped UPDATE grant is compared as a set**, because MOD-010's review
--     showed ten grant-widenings passing 43/43 against a hand-written list of names. The
--     address is in it for exactly one writer (MOD-009's erasure) and the trigger is what
--     bounds that; adding the link, the role or the window to it would make the trigger the
--     only control over what an invitation *is*.
BEGIN;
DO $$
DECLARE
    want_columns constant text[] := ARRAY[
        'accepted_at', 'accepted_identity_id', 'correlation_id', 'created_at', 'created_by',
        'email_normalized', 'expires_at', 'invitation_id', 'revoke_reason', 'revoked_at',
        'revoked_by', 'role_id', 'supersedes_invitation_id', 'tenant_id', 'token_hash'];
    want_grant constant text[] := ARRAY[
        'accepted_at', 'accepted_identity_id', 'email_normalized', 'revoke_reason',
        'revoked_at', 'revoked_by'];
    got text[];
BEGIN
    SELECT array_agg(a.attname ORDER BY a.attname) INTO got
      FROM pg_attribute a
     WHERE a.attrelid = 'iam.invitations'::regclass AND a.attnum > 0 AND NOT a.attisdropped;
    IF got <> want_columns THEN
        RAISE EXCEPTION
            'CHECK 116 FAILED: iam.invitations carries % and the pin says %',
            array_to_string(got, ', '), array_to_string(want_columns, ', ');
    END IF;

    SELECT array_agg(a.attname ORDER BY a.attname) INTO got
      FROM pg_attribute a
     WHERE a.attrelid = 'iam.invitations'::regclass AND a.attnum > 0 AND NOT a.attisdropped
       AND has_column_privilege('veyro_iam_app', a.attrelid, a.attname, 'UPDATE');
    IF got <> want_grant THEN
        RAISE EXCEPTION
            'CHECK 116 FAILED: veyro_iam_app may update % on iam.invitations and the pin '
            'says %', array_to_string(got, ', '), array_to_string(want_grant, ', ');
    END IF;

    -- The scopes are insert-only: an invitation whose clubs could change after it was sent is
    -- a link whose meaning moved under the person holding it.
    SELECT array_agg(a.attname ORDER BY a.attname) INTO got
      FROM pg_attribute a
     WHERE a.attrelid = 'iam.invitation_scopes'::regclass AND a.attnum > 0
       AND NOT a.attisdropped
       AND has_column_privilege('veyro_iam_app', a.attrelid, a.attname, 'UPDATE');
    IF got IS NOT NULL THEN
        RAISE EXCEPTION
            'CHECK 116 FAILED: an invitation''s clubs became editable (%)',
            array_to_string(got, ', ');
    END IF;
END $$;
ROLLBACK;

\echo 'tenant isolation: 116/116 checks passed'
